	s='<p>Find the Business Name, Email Address and Website associated with each facebook page.</p>'
	if(ih.indexOf(s) != -1) {
	var run = function() {};
	run.prototype.f = function() {
			GM_addStyle('body,p,h2,h1,h3,h4,ul,li,form,input,span,p,div,textarea,select,tr,td,fieldset,img,table {margin:0 !important;padding:0 !important;font-size:12px !important;}');
			GM_addStyle('.container {margin:0 !important;width:100% !important;padding:0 !important;margin-top:0px !important;top:2000px}'); // width:1100px=default
			GM_addStyle('.panel-primary {position:absolute;top:1000px;}');
			GM_addStyle('#submitButton {width:20% !important;height:150px;left:80%;position:absolute;top:2000px}');			
			GM_addStyle('.exe {border-bottom:1px solid #a2a2a2;cursor:pointer;}');
			GM_addStyle('.exe:hover {background-color:LightGreen;}');
			GM_addStyle('td {border:1px solid black;}');
			
			var o = {
				fbUrl : document.getElementsByTagName('a')[0].innerHTML,
				emails: [],
				debugLabel: document.getElementsByTagName('label')[0],
				q: [document.getElementById('business_name'),
					document.getElementById('email_address'),
					document.getElementById('web_url')]
			}
			
			for(var i = 0; i <o.q.length; i++) {
				o.q[i].placeholder = '';
			}
			
			console.log(o);
			function scrapeFacebook() {
				GM_xmlhttpRequest({
						method: 'GET',
						url: o.fbUrl,
						onload: function (response) {
							var rs = response.responseText;
							//console.log(rs);
							if (response.status > 200) {
								document.body.style.backgroundColor = 'aqua';
								exit(response.status);
							}
							else if(!rs.indexOf('>Page Info</span></a>') == -1 ||
								rs.indexOf('unofficial page') != -1) {
								document.body.style.backgroundColor = 'silver';
								o.debugLabel.innerText = 'Unoffical Page - R/A';
								
							}
							
							var emailReg = /([a-z0-9]+([_\.-][a-z0-9]+)*(@|[ ]{0,}[\[\(] *at *[\]\)][ ]{0,}|&#064;|%40)([a-z0-9]+([\.-][a-z0-9]+)*)+\.[a-z]{2,})/gi;
							var x;
							while(x = emailReg.exec(rs)) {
								//console.log(x);
								o.emails.push(x);
							}
							if(o.emails.length == 1) {
								o.q[1].value = o.emails[0][0].replace(/&#064;/, '@');
								//o.q[1].value = o.q[1].value.clean_string_to_array().join('');
								if(o.q[1].value.indexOf('@') == -1) {
									//error
									console.log('broken email attempt');
									document.body.style.backgroundColor = 'aqua';
									exit('123');
								}
							}
							else if(o.emails.length == 0) 
								o.q[1].value = 'no email';
							else {
								for(var i = 0; i < o.emails.length; i++) {
									var exe = document.createElement('div');
									document.body.appendChild(exe);
									exe.innerText = o.emails[i][0].replace(/&#064;/, '@');
									exe.className = 'exe';
									exe.onclick = function() {
										o.q[1].value = this.innerText;
										try_sbm();
									}
								}
							}
							
							
							//var dom =  new DOMParser().parseFromString(rs, 'text/html');
							console.log(rs);
							
							//domText should result in the First class of _5ay5 which should contain all of the relevent data
							var reg = /<code class="hidden_elem" id="u_0_[^"]+"><!-- <div class="_5ay5">((.|\s)*?(?=-->|$)|$)/; 
							var domText = reg.exec(rs)[1].trim();
							domText = '<div class="_5ay5">' + domText; 
							var domText = domText.replace(/-->$/,'');
							//console.log(domText);
							dom = new DOMParser().parseFromString(domText, 'text/html')
							dom.body.innerHTML = dom.body.innerHTML.replace(/<div class="_50f8 _50f4">([^<]+)/g, 'PLACEHOLDERBREAKHERE<br><div class="_50f8 _50f4">$1 - ');
							var debugText = dom.body.innerText.replace(/[\n]+/g, '\n');
							debugText = debugText.split('PLACEHOLDERBREAKHERE');
							for(var i = 0; i < debugText.length; i++) {
									if(debugText[i].match(/^Website - /)) {
										var websites = debugText[i].replace(/Website - /, '').trim();
									}
									
									var debugDiv = document.createElement('div');
									debugDiv.innerText = debugText[i] + '\n' ;
									debugDiv.style.borderTop ='1px solid black';
									document.body.appendChild(debugDiv);
							}
							

							
							//console.log(dom.body.innerText);
							
							//console.log(dom);
							
							var webDiv = dom.getElementsByTagName('div');
							//console.log(webDiv[5].innerHTML);
							var websites = [];
							var allInfoDivs = [];
							//console.log(webDiv);
							
							//~ console.log(dom.getElementsByClassName('_50f8 _50f4'));
							//console.log(dom.getElementsByClassName('_50f8 _50f4')[0].innerText);
							
							
							
									if(webDiv[i].className == '_2kcr _42ef') {
										var websitesString = parent.innerText.replace(/^Website/,'').trim();
										websitesString = websitesString.replace(/[\r\n\s\t]+/g, ' ');
										websites = websitesString.split(' ');
										if(websites.length == 1) {
											o.q[2].value = websites[0];
										}
										else if (websites.length > 1){
											for(var i = 0; i < o.websites.length; i++) {
												var exe = document.createElement('div');
												document.body.appendChild(exe);
												exe.innerText = o.emails[i];
												exe.className = 'exe';
												exe.onclick = function() {
													o.q[2].value = this.innerText;
													try_sbm();
												}
											}
										}
									}
							
							//var nameDiv = dom.getElementsByClassName('_4ywd');
							var nameReg = /<div class="_2q5c"><div class="_tum">About ([^<]+)<\/div>/;
							var name = nameReg.exec(rs);
							if(!name) {
								document.body.style.backgroundColor = 'aqua';
								exit('no biz name on site... correct url?');
							}
							else {
								name = name[1].trim();
								o.q[0].value = name;
							}
							
							
							

						}
				});
			}
			scrapeFacebook();
		}
		new run().f();
	}
	
	
