			p = p.replace(/:$/, ''); // Final ":"
			p = p.split('the website is');
			//~ p = /The Company Name is: ([^,]+), the website is ([^$]+)$/.exec(p);
			// e.g. "Ikatu International", "http://www.ikatuinternational.org/"
			var o = {
				comp: p[0].trim().replace(/,$/, ''), // Trailing comma
				url: p[1].trim(),
				domain: null,
				hl_strings: null,
				q: [
					document.getElementById('Field1')					
				],
			}
			//AMT__Global_Vars.copyInp = o.lastName;
			o.hl_strings = [
				//~ {string: o.firstName, color: 'yellow'},
				//~ {string: 'postal code', color: 'yellow', scrollIntoView: true},
				{string: 'postal code', color: 'yellow'},
				{string: 'zip code', color: 'yellow'},
				{string: 'postal', color: 'yellow'},
				{string: 'zip', color: 'yellow'},
				{string: o.comp, color: 'pink'},
				{string: 'contact', color: 'pink'},
				//~ {string: o.email, color: 'LightSalmon'},
				//~ {string: o.phone, color: 'Plum'}
			];
			if (o.url == '') {
				o.domain = '';
			} else if (!/^http/.exec(o.url)) {
				o.domain = o.url;
				o.url = 'http://' + o.url;
			} else {
				o.domain = o.url.replace(/^https?:\/\/(www\d*\.|)/, '');
			}
			console.log(o);
			/**BEGIN ITEMS**/
			var d1 = ''.div({
				style:'position:absolute;left:30%;width:50%;height:400px;top:0px;background-color:#eee;border:1px solid blue;'
			});
