	// Lowytech
	// Lookup the Status of a US Patent Application
	//
	//~ s = '<p>1) Go to http://publicpair.com.<br>\n2) Type in the captcha (to prove you are human).<br>';
	s = '<p>1) Go to http://portal.uspto.gov/pair/PublicPair .<br>\n2) Type in the captcha (to prove you are human).<br>';
	if  (
		ih.indexOf(s) != -1
		)
	{
		var run = function() {};
		run.prototype.f = function() {
			console.log('');
			GM_addStyle('body,p,h2,h1,h3,h4,ul,li,form,input,span,p,div,textarea,select {margin:0;padding:0;font-size:12px !important;}');
			GM_addStyle('.container {margin:0 !important;padding:0 !important;margin-top:20px !important;}'); // width:1100px=default
			GM_addStyle('.panel-primary {position:absolute;top:1000px;}');
			
			var td = document.getElementsByTagName('td');
			var o = {
				num: td[1].innerText.trim(),
				q: [
					document.getElementById('pa_status'),
					document.getElementById('pa_status_date')
				]
			}
			
			setInterval(uspto, 10000); // Every 10s.
			uspto(); // Init
			
			function uspto() {
				var data =
					'loadImages=LoadAllImages&searchType=&isSubmitted=isSubmitted&selectedApplication=undefined'+
					'&dosnumber='+encodeURIComponent(o.num)+
					'&historyNumber=&isHistorySelected=&submitButtonClicked=submitButtonClicked&AppSearchType=appId&AppSearchType='+
					'&selecteddosnum='+encodeURIComponent(o.num)+
					'&lang=DINO&testHidden=appId&selectedSearchOption=&public_selectedSearchOption=pair_applicationSearchoption&is_pair_new_search=appId'+
					'&pair_control_no_search=&paramForXmlDownload=&appSelectedType=appId'+
					'&dosnum='+encodeURIComponent(o.num)+
					'&lang=DINO&dosnumsele=++++...+++++';
				GM_xmlhttpRequest({
					method: "POST",
					url: 'http://portal.uspto.gov/pair/PublicPair',
					data: data,
					headers: {
						"Content-Type": "application/x-www-form-urlencoded"
					},
					onload: function(response) {
						var rs = response.responseText;
						if (response.status != 200) {
							return;
						}
						
						// Okay?
						// e.g
						var reg = /Application Number:        <\/td>[\r\n\t\s]+      <td align="left" class="wpsTableNrmRow" headers="r1c1" width="330">([^<]+)<\/td>/.exec(rs);
						if (reg) {
							reg = reg[1].replace(/[^\d]/g, '');
							if (reg != o.num) {
								sbm = false;
								console.log('APP NUM != o.num: ' + reg);
							}
						} else {
							sbm = false;
						}
						//~ if  (
							//~ rs
							//~ .replace(/[\/,]/g, '')
							//~ .indexOf('Application Number:        <td>\n      <td align="left" class="wpsTableNrmRow" headers="r1c1" width="330"> '+o.num+' <td>') == -1
									 //~ 'Application Number:        <td>\n      <td align="left" class="wpsTableNrmRow" headers="r1c1" width="330"> 10131437 <td>'
							//~ )
						//~ {
							//~ console.log(rs
							//~ .replace(/[\/,]/g, ''));
							//~ return;
						//~ }
						
						// sbm
						var sbm = true;
						
						// e.g. Abandoned  --  Failure to Respond to an Office Action
						var reg = /Status:<\/td>[\r\n\t\s]+<td class="wpsTableNrmRow" headers="r2c2" width="263">([^<]+)<\/tr>/.exec(rs);
						if (reg) {
							o.q[0].value = __js_clean_html_str(reg[1]).trim();
						} else {
							sbm = false;
						}
						// e.g. 05-01-2008 
						var reg = /Status Date:<\/td>[\r\n\t\s]+<td class="wpsTableNrmRow" headers="r3c2" width="263">([^<]+)<\/td>/.exec(rs);
						if (reg) {
							o.q[1].value = __js_clean_html_str(reg[1]).trim();
						} else {
							sbm = false;
						}
						
						// sbm
						if (sbm && o.q[0].value != '' && o.q[1].value != '') {
							doSubmit();
						}
					}
				});
			}
		}
		new run().f();
	}
	
