			var a = document.getElementsByTagName('a');
			
			var o = {
				founders: [],
				founders_ceo: [],
				q: []
			}
			for (var i = 1;i<=6;i++) {
				o.q.push(document.getElementById('Field'+i));
			}
			
			/*BEGIN ITEMS*/
			var d1 = document.createElement('div');
