		function Andrew_Ryan_guidestar_stats__gsIframeSearch() {
			
			//~ d1.style.height = '100px';
			//~ d3.style.zIndex = '10';
			d3.src = 'http://www.guidestar.org/SearchResults.aspx';
			
			var doSearch = true;
			
			// postMessage
			var ifr_intv = setInterval(function() {
				d3.contentWindow.postMessage({
					task:		'AMT__Andrew_Ryan_guidestar_stats',
					name:		b,
					location:	loc,
					doSearch:	doSearch
				}, "*");
			}, 1200);
			
			// watch for complete
			window.addEventListener("message", Andrew_Ryan_guidestar_stats__gsIframeSearch__complete, false);
			function Andrew_Ryan_guidestar_stats__gsIframeSearch__complete(event)
			{
				var v = event.data;
				console.log(v);
				
				// clear intv search
				if (v.key == 'AMT__Andrew_Ryan_guidestar_stats__clearInterval') {
					//clearInterval(ifr_intv);
					doSearch = false; // !! cancel searches !!
					return;
				}
				
				if(v.key == 'AMT__Andrew_Ryan_guidestar_stats__numResults')
				{
					var num = v.data.numResults * 1;
					var match = v.data.matchExists;
					console.log(match)
					console.log(v.data)
					if(num > 8 && !v.data.matchExists)
					{
						console.log('not accepting');
						AMT___Floater.skip();
					}
					else if(num <= 8 && v.data.matchExists)
					{
						AMT___Floater.accept();
					}
					else if(num < 8)
					{
						AMT___Floater.accept();
					}
					else
					{
						AMT___Floater.skip();
					}
					return;
				}

				
				//
				if (v.key == 'AMT__Andrew_Ryan_guidestar_stats__complete' && v.data) {
					Andrew_Ryan_guidestar_stats__scrapeGuidestarProfile(false, v.data);
					return;
				}
			}
		}
		
		
		
		
		
		
