		function Helpscore_init(array_dominant_color) { // rgb
			
			// set rgb of bold_pc
			bold_pc.style.backgroundColor = 'rgb('+array_dominant_color[0]+','+array_dominant_color[1]+','+array_dominant_color[2]+')';
			
			// dm hsl
			var dm_hsl = rf.general_functions__color__rgbToHsl(
				array_dominant_color[0],
				array_dominant_color[1],
				array_dominant_color[2]
			); // >[]
			//~ console.log(array_dominant_color);
			//~ console.log(dm_hsl);
			
			// Loop through the given images and find the Euclidean distance.
			// HSL is array [0...360, 0...1, 0...1]
			// general_functions__color__hslDistance = function(hsl1, hsl2)
			var current = 1;
			var distance;
			//var found = false;
			for (var i in y) {
				//if (y[i].name == 'gray') continue;
				
				distance = rf.general_functions__color__hslDistance(dm_hsl, y[i].hsl);
				
				// add to distance for gray and silver !!
				if (y[i].name == 'gray' || y[i].name == 'silver' || y[i].name == 'pink')
					distance += 0.075
				// bring distance down for white !!
				if (y[i].name == 'white')
					distance -= 0.075
				// bring distance down for green !!
				//~ if (y[i].name == 'green')
					//~ distance -= 0.025
				// bring distance down for red !!
				if (y[i].name == 'red')
					distance -= 0.025
				// bring distance up for brown !!
				if (y[i].name == 'brown')
					distance += 0.025
				// bring distance up for olive !!
				if (y[i].name == 'olive')
					distance += 0.025
				// bring distance up for maroon !!
				if (y[i].name == 'maroon')
					distance += 0.025
				// bring distance up for black !!
				if (y[i].name == 'black')
					distance += 0.025
				// bring distance up for purple !!
				if (y[i].name == 'purple')
					distance += 0.025
				
				if (distance < current) {
					document.getElementById('color_'+y[i].name).checked = true;
					current = distance;
					color_is_set = true; // set this to true now!
				}
				
				document.getElementById('label_for_color_' + y[i].name).innerText += Math.round(distance * 10) / 10;
				
				//~ console.log(
					//~ y[i].name + ':' +
					//~ rf.general_functions__color__hslDistance(dm_hsl, y[i].hsl) // >0...1
				//~ )
			}
			
		}
		
		
