		/**
		 * get_num_brokers_on_page
		 * 
		 **/
		function get_num_brokers_on_page(rs) {
			var r = /<tr[^>]*>[\r\n\t\s]*<td[^>]*>([^<]*)<\/td><td[^>]*>([^<]*)<\/td><td[^>]*>([^<]*)<\/td><td[^>]*>([^<]*)<\/td><td[^>]*>([^<]*)<\/td>[\r\n\t\s]*<\/tr>/g;
			
			if (!r.exec(rs)) return 0;
			else r.lastIndex = 0;
			
			var num = rs.match(r).length;
			return num;
		}
