			function get_images(url) {
				new AMT___requests_factory().xhr_with_disk_cache({
					URL: url,
					check_pre_write_to_disk: function(options) { // Return TRUE to write to disk. Return FALSE to not write to disk.
						if (options.response.status != 200) {
							return false;
						}
						return true;
					},
					success_callback: function(options) {
						var rs = options.response.responseText;
						if (options.response.status != 200) return;
						var r = JSON.parse(rs);
						console.log(r);
						if (!r.data) {
							d1_content.appendChild(' !r.data '.div({
								style: 'border:4px double blue;font-size:1.4em;display:inline-block;'
							}));
							return;
						}
						if (r.data.length == 0) {
							d1_content.appendChild('0 Results'.div({
								style: 'border:4px double blue;font-size:1.4em;display:inline-block;'
							}));
							return;
						}
						// Loop
						var x;
						var count = 0;
						for (var i in r.data) {
							var x = r.data[i];
							// Set global....
							if (o.images_loaded[ x.id ]) {
								continue; // Already on page...
							} else {
								o.images_loaded[ x.id ] = true;
							}
							var n = 'https://graph.facebook.com/'+x.id+'?'+o.at;
							// Update o.max_images_possible counter.
							o.max_images_possible++;
							//~ if (Object.keys(o.images_loaded).length > 100) break; // temp..............
							// Retrieve image details:
							//		'https://graph.facebook.com/'+this.graph_id+'?'+o.at
							// To get picture now without getting details:
							// 		'https://graph.facebook.com/v2.6/'+x.id+'/picture?'+o.at
							if (count < o.max_to_load) {
								check_image(n);
							} else { // add to array
								o.images_to_load.push(n);
							}
							count++;
						}
						update_counter();
						// Append a blank div for spacing.
						o.get_loaded++;
						//~ test_images_loaded();
					}
				});
			}
