			function acceptable(w, h) {
				// If less than 500 (700 required)
				// then remove.
				if (w < 690) {
					return false;
				}
				// Width needs to be smaller than height*.98
				// E.g. w=100, h=102, h-new = 102*.98 = 100
				// E.g. w=100, h=103, h-new = 103*.98 ~= 100.3
				if (w < h * .97) {
					return false;
				}
				// Default=true
				return true;
			}
			// check_image
			// Scrape "name" and Comments for "dog"
			function check_image(u) {
				new AMT___requests_factory().xhr_with_disk_cache({
					URL: u,
					check_pre_write_to_disk: function(options) { // Return TRUE to write to disk. Return FALSE to not write to disk.
						if (options.response.status != 200) {
							return false;
						}
						return true;
					},
					success_callback: function(options) {
						var rs = options.response.responseText;
						if (options.response.status != 200) return;
						var r = JSON.parse(rs);
						console.log(r);
						if (!r || !r.images) {
							//~ alert('bad image?');
							console.log('bad image?');
							console.log(r);
							return;
						}
						var im_most;
						//~ var im_acceptable;
						var curr = 0;
						for (var i in r.images) {
							var sz = r.images[i].width*r.images[i].height;
							var ac = acceptable(r.images[i].width, r.images[i].height);
							if (sz > curr && ac) {
								im_most = r.images[i];
								curr = sz;
								//~ // Set acceptable on first image.
								//~ if (!im_acceptable) {
									//~ im_acceptable = r.images[i];
								//~ }
							}
						}
						if (im_most) {
							var ob = {
								full: im_most.source,
								small: r.source,
								r: r,
								is_dog: false
							}
							// Add the image
							add_img(ob);
							//~ add_img(r.source);
							// Increment found counter
							o.found_good_images++;
							// Check dog
							check_dog(r, im_most.source);
						} else {
							// Increment completed counter here.
							o.image_requests++;
							update_counter();
						}
					}
				});
			}
			function add_dog(r, full) {
				//~ d1c.style.display = 'block';
				//~ if (!d1.isSmall) {
					//~ d1.style.height = ((d1.style.height.replace(/px/, ''))*1 - 200) + 'px';
					//~ d1.style.top = '230px';
					//~ d1.isSmall = true;
				//~ }
				var ob = {
					full: full,
					small: r.source,
					r: r,
					is_dog: true
				}
				add_img(ob);
			}
			function check_dog(r, full) {
				//~ if (r.comments)
					//~ console.log((JSON.stringify(r.comments)).toLowerCase());
				var io = (r.comments) ? (JSON.stringify(r.comments)).toLowerCase() : null;
				if (io && io.indexOf('dog')) {
					console.log('====='+io.indexOf('dog'));
					console.log((JSON.stringify(r.comments)).toLowerCase());
				}
				if (r.name && /dog|pup/i.exec(r.name)) {
					add_dog(r, full);
				} else if (
					r.comments &&
					io &&
					(
					io.indexOf('dog') != -1 ||
					io.indexOf('pup') != -1)
				) {
					add_dog(r, full);
				}
			}
