						//~ }
						div.onmouseover = function() {
							var x = document.getElementsByClassName(this.className);
							for (var i in x) {
								if (i == 'length') break;
								x[i].style.backgroundColor = 'LightGreen';
							}
						}
						div.onmouseout = function() {
							var x = document.getElementsByClassName(this.className);
							for (var i in x) {
								if (i == 'length') break;
								x[i].style.backgroundColor = '';
							}
						}
						
						c++;
