					//~ var pr = JSON.parse('{'+m[1].replace(/'/g, '"')+'}');
					
					
					// FIRST run?
					if (first) {
						first = false;
						var t = table.getElementsByTagName('input');
						t[0].value = pr.property_name;
						t[1].value = pr.city;
						continue;
					}
					
					var tr = document.createElement('tr');
					table.appendChild(tr);
					var td = document.createElement('td');
