	// Tucker Severson
	//
	//
	// 
	s = '<li>Enter the 7-digit FIPS code for cities, or 5-digit code for counties,&nbsp;of the given place in the following format: xxxxxxx</li>';
	if(ih.indexOf(s) != -1)
	{
		var run = function(){}
		run.prototype.f = function() {
			GM_addStyle('body,p,h2,h1,h3,h4,ul,li,form,input,span,p,div,textarea {margin:0;padding:0;font-size:14px;}');
			GM_addStyle('.panel-primary {position:absolute;top:1000px;left:50% !important;}'); // Left:50%
			GM_addStyle('.container {margin:0 !important;padding:0 !important;margin-top:400px !important;}');//width:40% !important;	
			//~ GM_addStyle('body {width:40%;margin-top:50px;}');
			GM_addStyle('input {width:90%;}');
			GM_addStyle('.div-highlight {position:absolute;top:1200px;}');
			GM_addStyle('.exe:hover {background-color:LightGreen;}');
			GM_addStyle('#mturk_form {margin-top:1000px;}');
			
			var td = document.getElementsByTagName('td');
			var o = {
				city: td[1].innerText.trim(),
				state: td[3].innerText.trim(),
				population: td[5].innerText.trim(),
				q: [
					document.getElementById('fips_code'),
				],
				//~ nas: [],
				//~ divs: [],
				//~ inputs: [],
				bold: null,
				//~ mbold: null,
				//~ auto: false,
				//~ store_no_the:null,
				//~ mall_no_the:null,
			} // "city of, town of"
			// Remove st abbr from city (their data seems broken)
			// Changes "Kasson, MN" to "Kasson".
			o.city = o.city.replace(new RegExp(', '+o.state+'$', 'i'), '');
			o.bold = o.city.clean_string_to_array();
			/* BEGIN ITEMS */
			var d1a = ''.div({
				style:
				'position:absolute;top:60px;'+
				'left:0;width:50%;height:600px;background-color:#eee;border:1px solid blue;overflow:auto;',
				a: true, // Append to body
			});
			var d1b = ''.div({
				style:
				'position:absolute;top:60px;'+
				'left:50%;width:49%;height:600px;background-color:#eee;border:1px solid blue;overflow:auto;',
				a: true, // Append to body
			});
			var d3 = (o.population != '' ? MT___numberWithCommas(o.population) : '--').div({
				style:
				'position:absolute;top:0px;'+
				'left:0;width:99%;height:20px;background-color:#eee;border:1px solid blue;overflow:auto;',
				a: true, // Append to body
			});
			// Inputs....
			var ef = new AMT___events_factory();
			var d2a = document.createElement('input');
			d2a.setAttribute('type','text');
			d2a.setAttribute('style',
				'position:absolute;top:20px;left:0;width:50%;height:40px;'
			);
			ef.mouseup__delete_range({
				element: d2a,
				callback: function(input_object) {
					input_object.element.blur();
				}
			});
			d2a.addEventListener('keydown', ef.keydown__blur_field, true);
			d2a.out = d1a;
			d2a.value = o.city + ',' + o.state;
			d2a.onblur = function () { stores(this); };
			document.body.appendChild(d2a);
			var d2b = document.createElement('input');
			d2b.setAttribute('type','text');
			d2b.setAttribute('style',
				'position:absolute;top:20px;left:50%;width:49%;height:40px;'
			);
			ef.mouseup__delete_range({
				element: d2b,
				callback: function(input_object) {
					input_object.element.blur();
				}
			});
			d2b.addEventListener('keydown', ef.keydown__blur_field, true);
			d2b.out = d1b;
			d2b.value = o.city.replace(/ [^ ]+$/, '') + ',' + o.state; // Remove final word
			d2b.onblur = function () { stores(this); };
			document.body.appendChild(d2b);
			/* END ITEMS */
			
			// innerHeight
			new AMT___core_factory().el_innerHeight({
				// This set the elements d1,d1b, and d1c
				// to fill up the whole window, minus their
				// distance from page top (top:XX pixels;).
				elements: [
					d1a,d1b
				],
				offset: 60
			});
			// ...
			document.getElementById('submitButton').onclick = function(e) {
				e.stopPropagation();
				e.preventDefault();
				try_sbm();
				return false;
			}
			// init
			stores(d2a);
			if (d2a.value != d2b.value)
				stores(d2b);
			else d2b.value = '';
			// ...
			function stores(input) {
				input.value = input.value.replace(/, *,/g, ','); // clean space
				var x = input.value.split(',');
				input.out.innerHTML = '';
				var rf = new AMT___requests_factory();
				rf.database__select(
					{
						query: 'AMT__Tucker_Severson',
						encodeStrings: [ { city: x[0].trim(), state: x[1].trim().stateAbbrToFull() } ],
						__seed__: input,
					},
					process
				);
			}
			// ...
			function process(database_object) {
				// Note: type is now NULL
				// array_push($out_arr, [...]);
				// 		[ $row['state_abbreviation'], $row['state_fips'], $row['county_fips'], $row['entity_fips'], $row['name'], $row['type'], pop, col2]
				// database_object.responseObject = JSON.parse(rs);
				var input = database_object.__seed__;
				var out = input.out;
				var show = (input.value).div({style:'border-bottom:2px solid teal;'});
				// Show...
				out.innerText = '';
				out.appendChild(show);
				// 0...
				if (database_object.responseObject.length == 0) {
					out.appendChild('0 results!'.div());
					return;
				}
				
				// Loop
				// AUTO :: When 1 result and exact match and length >= 4.
				// 
				var auto = (database_object.responseObject.length == 1) ? true : false;
				//~ var first_word = d2.value.split(' ')[0].toUpperCase();
				//~ var auto = false;
				var unq_codes = {}; // Unique only!
				var first_result = null;
				var found_auto = false;
				var num_results = 0;
				var num_exact_match = 0;
				var is_county = false;
				var least = false; // population
				for (var i in database_object.responseObject) {
					//
					var x = database_object.responseObject[i]; // 0=store, 1=mall, 2=#
					// 
					if (x[4].indexOf('(pt.)') != -1) continue; // Skip these, they're odd.....
					if (x[4].indexOf('Balance of ') == 0) continue; // Skip these, they're odd.....
					//~ if (x[1].length == 1) x[1] = '0'+x[1];
					//~ if (x[2].length == 1) x[2] = '0'+x[2];
					//~ if (x[3].length == 1) x[3] = '0'+x[3];
					// 26/000/54321 & 26/123/00000 === Beware of these!
					// Not county or state but 0!
					
					if (x[4].indexOf('County') == -1 &&
						x[3] == '00000' &&
						x[7] != '00000'
					) {
						x[3] = x[7];
					}
					if (x[4].indexOf('County') == -1 &&
						x[3] == '00000'
					) {
						continue; // !skip
					}
					// Both 0s
					// This is a __State__
					if (x[2] == '000' && x[3] == '00000') continue; //  
					//~ console.log(x[3] == '00000');return;
					//~ console.log(x);return;
					// Code
					var code;
					if (x[4].indexOf(' County') != -1) {
						code = x[1] +''+ x[2];
						is_county = true;
					} else { // city / town, etc.
						code = x[1] +''+ x[3];
					}
					// Unique
					if (unq_codes[ code ]) {
						continue;
					}
					unq_codes[ code ] = true;
					// Type
					var type = / (city|town|township|county|village|borough)$/i.exec(x[4]);
					var name_initial = x[4];
					if (type) {
						type = type[0].trim()+': ';
						x[4] = x[4].replace(/ (city|town|township|county|village|borough)$/i, '');
					} else type = '';
					//
					var n1 = MT__bold(x[0], o.bold);
					var n2 = MT__bold(x[4], o.bold, {color:'blue'}).bold_string;
					var n3 = x[5];
					//
					var eldiv = document.createElement('div');
					eldiv.setAttribute('style','border-bottom:1px solid #a2a2a2;cursor:pointer;');
					eldiv.className = 'exe';
					eldiv.innerHTML = n2 + ' (<i>'+type+MT___numberWithCommas(x[6])+': '+code+'</i>)<br>&nbsp;&nbsp;&nbsp;&nbsp;'+x[1]+':'+x[2]+':'+x[3];
					// No state!
					//~ eldiv.innerHTML = n1 + ':' + n2 + ' (<i>'+MT___numberWithCommas(x[6])+')<br>&nbsp;&nbsp;&nbsp;&nbsp;'+x[1]+':'+x[2]+':'+x[3];
					eldiv.code = code;
					eldiv.onclick = function(e) {
						o.q[0].value = this.code;
						this.style.backgroundColor = 'LightGreen';
						try_sbm();
					}
					out.appendChild(eldiv);
					num_results++;
					if (out != d1a) continue; // Only d1a
					// Difference in population.
					if (!least) least = eldiv;
					eldiv.diff = Math.abs(o.population*1 - x[6]*1);
					if (eldiv.diff < least.diff && i < 8) { // Only top 8!
						least = eldiv;
					}
					if (i == 0) first_result = eldiv;
					if (
						(
							x[4].toLowerCase()			== o.city.toLowerCase() ||
							name_initial.toLowerCase()	== o.city.toLowerCase() ||
							x[4].toLowerCase()			== o.city.replace(/^(town of |city of |township of )/i, '').toLowerCase()
						) &&
						x[4].length >= 4
					   ) {
						if (i == 0)
							found_auto = true;
						num_exact_match++;
					}
					
				}
				// Least pop difference
				if (o.population != '')
					least.style.textDecoration = 'underline';
				//~ least.style.border = '2px solid teal';
				//~ if () {
					
				//~ }
				// None...
				if (num_results == 0) {
					out.appendChild('0'.div());
				}
				// Found auto and auto is the first result
				// And there is only one exact match.
				if (num_exact_match == 1 && found_auto) {
					first_result.click();
				}
				//~ if (found_auto && num_results == 1) {
					//~ first_result.click();
				//~ } else if (num_exact_match == 1) {
					
				//~ }
				var eldiv = document.createElement('div');
				eldiv.setAttribute('style','height:2000px;');
				out.appendChild(eldiv);
				//~ var eldiv = document.createElement('div');
				//~ eldiv.setAttribute('style','height:2000px;');
				//~ out.appendChild(eldiv);
			}
			function try_sbm() {
				if (!/^(0|\d{5}|\d{7})$/.exec(o.q[0].value)) {
					return false;
				}
				if (/00000$/.exec(o.q[0].value)) {
					return false;
				}
				// Still here...
				doSubmit();
			}
		}
		new run().f();return;
	}
