		// function requester_web_domains_make_words
		function requester_web_domains_make_words(rowSubmit) {
			var h2 = document.getElementsByTagName('h2')[1];
			h2.appendChild(document.createElement('br'));
			//
			
			// Make two rows of buttons
			var btn;
			for (var i in letters) {
				btn = document.createElement('input');
				btn.setAttribute('type','button');
				btn.setAttribute('id','');
				btn.setAttribute('style','margin-left:-1px;border:1px solid #eee;cursor:pointer;zoom:2;min-width:14px;');
				btn.value = letters[i];
				btn.onclick = requester_web_domains_make_words__btnclick;
				btn.rowSubmit = rowSubmit;
				h2.appendChild(btn);
				
				if (!rowSubmit) {
					btnsTop.push(btn)
				} else {
					btnsBtm.push(btn)
				}
			}
			//~ console.log(btnsTop);
			//~ console.log(btnsBtm);
		}
		// function requester_web_domains_make_words__btnclick
		function requester_web_domains_make_words__btnclick() {
			if (this.style.backgroundColor != '')
				return;
			
			q.value += ' ';
			
			for (var i in btnsTop) {
				if  (
					btnsTop[i].style.backgroundColor == ''
					)
				{
					btnsTop[i].style.backgroundColor = 'LightGreen';
					btnsBtm[i].style.backgroundColor = 'LightGreen';
					q.value += btnsBtm[i].value;
				}
				if  (
					btnsTop[i] == this ||
					btnsBtm[i] == this
					)
				{
					break;
				}
			}
			
			q.focus();
			q.value = q.value.trim();
			var word_tmp = q.value.replace(/ /g, '');
			//~ console.log(word_tmp);
			//~ console.log(word);
			
			if (q.value != '' && this.rowSubmit && word_tmp == word) {
				q.style.backgroundColor = 'LightGreen';
				doSubmit();
			}
		}
		
