			function update_debug_title() {
				// Watch o.q[0], o.q[1]
				
				if (!o.debug_title) return;
				
				var type = o.q[1].value,
					amt = o.q[0].value + '\n';
				
				if (o.q[1].value == 'select one') {
					type = '\n';
				}
				
				o.debug_title.innerText = amt + type;
				
				//~ switch (o.q[1].value) {
					//~ case 'select one':
						//~ type = '';
						//~ break;
				//~ }
			}
			// window.onkeypress
			//~ window.addEventListener('keypress', update_debug_title, false);
			
			// window.onkeypress
			window.addEventListener('keypress', function(e) {
				var c = e.keyCode;
				console.log(c);
				
				setTimeout(update_debug_title, 80);
				
				if(c == 45) {
					var img = document.getElementsByTagName('img');
					for(var i = 0; i < img.length; i++) {
						if(!img[i].isSmall) {
							img[i].click();
							break;
						}
					}
					e.preventDefault();
					e.stopPropagation();
					return false;
				}
				
				if(c >= 48 && c <= 57 || c == 46) {
					if(o.firstEntry && document.activeElement == o.q[0] &&
					   AMT__Global_Vars.scriptVars['reset top input'] == 1) {
						o.q[0].value = '';
					}
				}
				o.firstEntry = false;
				
				//
				if  (
					c == 13
					)
				{
					document.getElementById('submitButton').click();
					e.preventDefault();
					e.stopPropagation();
					return false;
				}
				
				// Semi-colon iterate o.q[3]
				if (c == 59) {
					o.q[0].value = '';
					o.q[1].value = 'select one';
					o.q[2].value = '';
					switch (o.q[3].value) {
						case 'select one':
							o.q[3].value = 'page 404';
							break;
						case 'page 404':
							o.q[3].value = 'no images';
							break;
						case 'no images':
							o.q[3].value = 'poor images';
							break;
						case 'poor images':
							o.q[3].value = 'page 404'; // Back to 2nd
							break;
					}
					e.preventDefault();
					e.stopPropagation();
					return false;
				}

				
				if(c == 116 || c == 110) {
					o.q[0].value = '';
					o.q[1].value = 'select one';
					o.q[2].value = '';
					o.q[3].value = 'page 404';
					e.preventDefault();
					e.stopPropagation();
					return false;

				}
				if(c == 121 || c == (AMT__Global_Vars.scriptVars['m is "no image" (not count)'] == '1' ? 109 : -1)) {
					o.q[0].value = '';
					o.q[1].value = 'select one';
					o.q[2].value = '';
					o.q[3].value = 'no images';				
					e.preventDefault();
					e.stopPropagation();
					return false;

				}

				if(c == 117 || c == 44 ) {
					o.q[0].value = '';
					o.q[1].value = 'select one';
					o.q[2].value = '';
					o.q[3].value = 'poor images';
					e.preventDefault();
					e.stopPropagation();
					return false;

				}
				
				if  (c == 43) {
					o.q[0].value = '';
					o.q[0].focus();
					e.preventDefault();
					e.stopPropagation();
					return false;
				}
				if  (
						(c >= 106 && c <= 108) ||
					c == 59 || c == 39 ||
					c == 111 ||
					c == 105
					)
				{
				
					c = (c == 59 && AMT__Global_Vars.scriptVars['m is "no image" (not count)'] == '0') ?109:c; //;
					c = (c == 39) ?110:c; //'
					
					c = (c == 111)?110:c; //
					c = (c == 105)?109:c; //
					
					e.preventDefault();
					e.stopPropagation();
					
					c = (106 - c) * -1; // = 0, = 1, ...
					c++; // = 1, = 2, ...
					
					o.q[1].selectedIndex = c;
					o.q[2].focus();
					return false;
				}
				if  (
						(c >= 100 && c <= 104) ||
					 (c == 109 && AMT__Global_Vars.scriptVars['m is "no image" (not count)'] == '0')
					)
				{
					c = (c == 100) ? 101: c;
					c = (c == 109) ? 105 : c;  
					
					e.preventDefault();
					e.stopPropagation();
					
					c = (101 - c) * -1; // = 0, = 1, ...
					c++; // = 1, = 2, ...
					
					o.q[1].selectedIndex = c;
					o.q[2].focus();
					return false;
				}
				
			}, false);
			
			/**
			 * appendTxt
			 * 
			 * NOTE: Added Oct22 2014: max-width 450px;
			 */
			function appendTxt(div, text, out_inp, isHighlighted) {
				
				var x = document.createElement('div');
				x.setAttribute('style', 'display:block;max-width:450px;');
				
				// MAKE BUTTONS
				
				// array of returned buttons
				var return_buttons_array = [];
				
				var text = text.split(' ');
				for (var i in text) {
					
					var btn = document.createElement('button');
					btn.setAttribute('style', 'border:0;margin:0;margin-right:2px;');
					// isHighlighted
					if (isHighlighted)
						btn.style.border = '2px solid teal';
					btn.innerText = text[i];
					if (text[i] == '<Size>') {
						btn.style.borderStyle = 'double';
						btn.style.borderWidth = '4px';
					}
					//onclick
					btn.onclick = function(e) {
						this.style.border = '4px solid teal'; //
						var n = this.innerText.replace(/[^\d\.]/g, '') * 1;
						out.out_element.value = n;
						out.out_element.focus();
						out.out_element.select();
						e.preventDefault();
						e.stopPropagation();
						return false;
					}
					
					x.appendChild(btn);
					return_buttons_array.push(btn);
				}
				
				div.appendChild(x);
				return return_buttons_array;
			}
			// function fillFirstNumber
			//(out.div.getElementsByTagName('input'))
			function fillFirstNumber(out_input, inputs) {
				for (var i in inputs) {
					if (i == 'length') break;
					var n;
					if (n = /([\d\.]+)/.exec(inputs[i].innerText)) {
						if (!/\d/.exec(n)) continue;
						out_input.value = n[0].trim();
						out_input.focus(); // focus
						out_input.select(); // focus
						inputs[i].style.border = '4px solid teal';
						break;
					}
				}
			}
