		function WChan_SEC_scrape__create_textareas(rs, search_str, out_div) {
			var index = 0;
			//var more = true;
			var str;
			var txt;
			var inp;
			var rs_upper = rs.toUpperCase().replace(/\n/g, ' ');
			var init = rs_upper.indexOf(search_str);
			if (init) {
				var c = 0;
				while (index != -1 && c<10) {
					index = rs_upper.indexOf(search_str, index+1);
					
					if (index == -1) break;
					
					str = rs.substr(index-200, 600);
					
					//
					inp = document.createElement('textarea');
					inp.setAttribute('style','width:10%;height:180px;');//margin-top
					inp.value = rs.substr(index-20, 60);
					inp.readOnly = true;
					out_div.appendChild(inp);
					//out_div.appendChild(document.createTextNode(index));
					
					//
					txt = document.createElement('textarea');
					txt.setAttribute('style','width:89%;height:180px;');//vertical-align:middle;
					txt.onclick = function() {
						var x = this.parentNode.getElementsByTagName('textarea');
						for (var i in x) {
							if (i == 'length') break;
							x[i].style.backgroundColor = '';
						}
						this.style.backgroundColor = 'LightGreen';
						
						this.parentNode.complete = this.id;
						
						//
						if (d1.complete && d1b.complete) { // start/end as well as "is complete"
							// 
							console.log(d1b.complete - d1.complete);
							console.log(d1.complete);
							console.log(d1b.complete);
							var x = document.getElementsByName('summary')[0];
							
							if (d1.complete*1 < d1b.complete*1) {
								x.value = SEC_PAGE.substr(d1.complete, d1b.complete - d1.complete); // range
							} else {
								x.value = SEC_PAGE.substr(d1.complete); // to end
							}
							
							x.scrollIntoView();
							//x.focus();
							
						}
					}
					txt.id = index;
					txt.value = str;
					txt.readOnly = true;
					out_div.appendChild(txt);
					
					//
					out_div.appendChild(document.createElement('hr'));
					
					c++;
				}
				
				var x = document.createElement('div');
				x.setAttribute('style','height:1600px;');
				out_div.appendChild(x)
			}
		}
