		function KC_transcripts_morningstar__countMatches(rs) {
			var r, r2;
			if (r = rs.match(/trans/gi)) {
				r = r.length;
			} else r = 0;
			console.log('r ' + r);
			if (r2= rs.match(/inno/gi)) {
				r2 = r2.length;
			} else r2= 0;
			console.log('r2 ' + r2);
			r = Math.round(r + r2);

			return r;
		}
