	function Facebook___textarea_contact_details(style, callback_function) {
		var d
		d = document.createElement('textarea');
		//d.setAttribute('id','d2b');
		d.setAttribute('style',style);
		d.onblur = function() {
			// facebook
			this.value = this.value.trim();
			
			if (this.value.indexOf('?sk=info') == -1 && this.value.indexOf('/info') == -1)
			{
				if (/\d{7,}$/.exec(this.value))
					this.value += '?sk=info';
				else if (this.value.indexOf('facebook.') != -1)
					this.value += '/info';
			}
			
			var txtarea = this;
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: this.value,
				onload: function (response) {
					var rs = response.responseText;
					
					txtarea.style.border = '2px solid LightGreen';
					
					if (response.status > 200) {
						return;
					}
					
					var r;
					var found = false;
					
					// on map
					r = /<div class="mtm ptm uiBoxWhite topborder">((.|\s)*?(?=<\/div>|$)|$)/.exec(rs);
					if (r) {
						r = r[1];
						r = r.replace(/<[^>]*>/g, ' ');
						r = r.replace(/[<>]/g, '');
						r = r.replace(/\s+/g, ' ');
						r = __js_clean_html_str(r).trim();
						txtarea.value = r;
						found = true;
					}
					
					// on right
					r = /<div><h4 class="uiHeaderTitle">Contact Info<\/h4><\/div><\/div><\/div><table[^>]*>((.|\s)*?(?=<\/table>|$)|$)/.exec(rs);
					if (r) {console.log(r);
						r = r[1];
						r = r.replace(/<[^>]*>/g, ' ');
						r = r.replace(/[<>]/g, '');
						r = r.replace(/\s+/g, ' ');
						r = __js_clean_html_str(r).trim();
						if (found)
							txtarea.value+= "\n"+r;
						else
							txtarea.value = r;
					}
					
					callback_function(response);
				}
			});
		}
		d.value = '';
		document.body.appendChild(d);
	}
