			var b = document.getElementsByTagName('b');
			var nm= document.getElementsByTagName('strong')[0].innerText;
			// Add an extra "b" element if necessary
			// e.g.: [<b>​963, Jung1-dong, Haeundae-gu​</b>​, <b>​Busan​</b>​, <b>​4129534​</b>​]
			if (b.length == 3) {
				b[3] = ''.div(); // Empty div
			}
			
			var addr1 = [];
			var addr2 = [];
			addr2.push(nm);
			for (var i = 0; i<=3; i++) {
				if (b[i] && b[i].innerText)
					addr1.push(b[i].innerText.trim())
			}
			for (var i = 0; i<=1; i++) {
				if (b[i] && b[i].innerText)
					addr2.push(b[i].innerText.trim())
			}
			
