			new AMT___core_factory().createScriptVar('S.Hass Use Proxy', '1');
			o.use_proxy = (AMT__Global_Vars.scriptVars['S.Hass Use Proxy'] == '1') ? true : false;
			//~ console.log(AMT__Global_Vars.scriptVars['S.Hass Use Proxy']);
			
