		// from john roberts
		function Daniel_Leffel_ebay__searchByImage() {
			d1.innerHTML = img_src;
			
			var url =
				'https://www.google.com/searchbyimage?espv=2&es_sm=106&biw=1242&bih=613&site=search&q="ebay"+"itm"'+ // add q="ebay"!
				'&image_url='+img_src +
				'&sa=X&ei=FpwSU86aBuGIygGP2YDYDg&ved=0CE8Q9Q8oAA';
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: url,
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status > 200) {
						document.body.style.backgroundColor = 'pink';
						return;
					}
					
					var r, m;
					
					// replace "Best Match" !!
					if (rs.indexOf('Best guess for this image:') != -1) {
						rs = rs.split('>Visually similar images</a></h3>');
						rs = rs.slice(1).join('>Visually similar images</a></h3>');
						
						rs = rs.replace(/Best guess for this image:[^<]{0,}<a[^>]+>[^<]+<\/a><\/div><\/div><div id="search"><!--a--><h2 class="hd">Search Results<\/h2><div id="ires"><ol[^>]+><li class="g"><!--m-->((.|\s)*?(?=<!--n-->|$)|$)/gi, '');
						
						if (rs.indexOf('Best guess for this image') != -1) {
							alert('Best guess for this image');
							return;
						}
					}
					
					// results
					r = /<h3 class="r"><a href="([^"]+)[^>]*((.|\s)*?(?=<!--n-->|$)|$)/g; // [^>]* added
					var count = 0;
					if (r.exec(rs)) {
						r.lastIndex = 0;
						while (m = r.exec(rs)) {
							// replace "harm your comp."
							m[1] = m[1].replace(/^\/interstitial\?url=/, '');
							
							if (!/^https?:\/\//.exec(m[1])) {
								alert('x');
								console.log(m);
								return;
							}
							
							// 1 = href
							// 2 = body
							
							var url = m[1];
							url = __js_clean_html_str(url);
							if (!/^http:\/\/www\.ebay\.com\/itm\//i.exec(url)) {
								continue; // skip!
							}
							
							var src = /imgurl=([^&]+)&amp;/.exec(m[2]);
							src = (src) ? src[1] : '';
							
							if (src == '')
								continue; // skip!
							
							var el = document.createElement('div');
							el.setAttribute('style', 'display:block;border-bottom:2px solid #a2a2a2;display:none;');
							el.setAttribute('id', 'div'+url);
							
							var el_im = document.createElement('img');
							el_im.setAttribute('style', 'float:left;width:110px;max-height:600px;');
							el_im.src = src;
							el_im.id = url;
							el_im.addEventListener('click', function() {
								document.getElementById('Q1Url').value = this.id;
								this.style.border = '3px solid LightGreen';
								if (/^http:\/\/www\.ebay\.com\/itm\//.exec(this.id)) {
									doSubmit();
								}
							}, false);
							
							var inner = m[2];
							inner = inner.replace(/<[^>]*>/g, ' ');
							inner = inner.replace(/[<>]/g, ' ');
							inner = inner.replace(/\s+/g, ' ');
							inner = __js_clean_html_str(inner);
							
							el.appendChild(el_im);
							el.appendChild(document.createElement('br'));
								
							var el_p = document.createElement('p');
							el_p.innerText = inner;
							el.appendChild(el_p);
							
							var cl = document.createElement('br');
							cl.setAttribute('style', 'clear:both;');
							el.appendChild(cl);
							
							d1.appendChild(el);
							
							// resolve the URL!
							// if the URL does not resolve to ebay.com/itm/... then 
							// leave div's display:none
							MT___resolveURL(
								url, //url, callback, seed
								function(response, seed) {
									document.getElementById('div'+seed).style.display = '';
								},
								url
							);
							
							if (count == 0) {
								//autofill first
								//d1.getElementsByTagName('img')[0].click();
								
							}
							count++;
						}
					}
					if (count != 0) {
						var el = document.createElement('div');
						el.setAttribute('style', 'height:2000px;');
						d1.appendChild(el);
					} else {
						d1.innerHTML = '0';
						// do Daniel_Leffel_ebay_items
						// (click to show)
						d2c.click();
					}
				}
			});
		}
		// ebay items keyword search
		function Daniel_Leffel_ebay_items() {
			
			d1.innerHTML = d2.value + '<br>';
			
			// url
			var url = "http://svcs.ebay.com/services/search/FindingService/v1";
			url += "?OPERATION-NAME=findItemsByKeywords";
			url += "&SERVICE-VERSION=1.0.0";
			url += "&SECURITY-APPNAME=DSOI6d2a3-384b-4232-8121-37761aad963";
			url += "&GLOBAL-ID=EBAY-US";
			url += "&RESPONSE-DATA-FORMAT=JSON";
			url += "&REST-PAYLOAD";
			url += "&keywords=" + encodeURIComponent(d2.value);
			url += "&paginationInput.entriesPerPage=8";
			//url += "&callback=_cb_findItemsByKeywords";
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: url, // href!
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status != 200) return;
					
					rs = JSON.parse(rs);
					console.log(rs);
					
					rs = rs.findItemsByKeywordsResponse[0].searchResult[0];
					
					if (!rs.item) {
						d1.innerHTML += '0';
						return;
					}
					
					// here?
					d1.innerHTML = '';
					
					rs = rs.item;
					
					var x;
					for (var i in rs) {
						x = document.createElement('img');
						x.setAttribute('style','float:left;width:50%;');
						x.src = (rs[i].galleryURL) ? rs[i].galleryURL[0] : 'http://';
						d1.appendChild(x);
						
						x = document.createElement('textarea');
						x.setAttribute('id', rs[i].viewItemURL[0]);
						x.setAttribute('style','width:44%;height:120px;zoom:0;cursor:pointer;');
						x.value = rs[i].title[0].trim();
						x.onclick = function() {
							this.style.backgroundColor = 'LightGreen';
							document.getElementById('Q1Url').value = this.id;
							if (/^http:\/\/www\.ebay\.com\/itm\//.exec(this.id)) {
								doSubmit();
							}
						}
						if (rs[i].title[0].toLowerCase().trim() == name.toLowerCase()) {
							x.style.border = '6px solid teal';
						}
						d1.appendChild(x);
						x.readOnly = true;
						
						
						
						//d1.appendChild(document.createElement('br'));
						x = document.createElement('hr');
						x.setAttribute('style','clear:both;');
						d1.appendChild(x);
						
						// auto click on first if exact name match/name.length>=10 ??
					}
					
					if (d1.innerHTML != '') {
						x = document.createElement('div');
						x.setAttribute('style','height:2400px;');
						//x.innerText = ' ';
						d1.appendChild(x);
					}
				}
			});
		}
