				//~ var reg = /id="LBD_VCID_c_secure_statuscheck_ctl00_contentplaceholder_uccaptcha30" value="([^"]+)"/.exec(rs);
				//~ if (!reg) {
					//~ err();
				//~ }
				//~ v.lbd = __js_clean_html_str(reg[1]);
				
				return v;
