			/**
			 * function check_accept
			 * 
			 * str1==str2 || str1 IN str2 || str2 IN str1
			 */
			function check_accept(str, phone) {
				//~ if (!AMT__Global_Vars.isPreview) return;
				//~ o.exact_name_match = o.name.clean_str_to_auto();
				if (o.check_accept_found) return;
				
				var str = str.clean_str_to_auto();
				if  (
					str == o.exact_name_match ||
					str.indexOf(o.exact_name_match) != -1 ||
					o.exact_name_match.indexOf(str) != -1
					)
				{
					console.log(str);
					console.log(o.exact_name_match);
					o.check_accept_found = true;
					AMT___Floater.accept();
				} else {
					var ld = new AMT___gen_functions().levensht(str, o.exact_name_match); // Returns INT `changes`
					var strlen = (str.length > o.exact_name_match.length) ? str.length : o.exact_name_match.length;
					var pct_similar = (strlen - ld) / strlen; // e.g. 10-9 / 10 = 10%. 20-4 / 20 = 80%.
					// 0 is completely dissimilar. 1 is identical.
					// AMT__Global_Vars.scriptVars['SP LevRatio']
					if (pct_similar >= AMT__Global_Vars.scriptVars['SP LevRatio'] * 1) {// Default=.9
						d2.style.border = '2px solid blue';
						console.log('ACCEPTED (LD=' + ld+') ('+str+')VS('+o.exact_name_match+')');
						o.check_accept_found = true;
						AMT___Floater.accept();
					}
				}
			}
			
