			function yelp() {
				d1c.innerHTML = '';
				d1c.appendChild(
					d2.value.div( {'style':'border-bottom:4px solid teal;width:100%;'} )
				);
				var u = 'http://www.yelp.com/search/snippet'+
						'?find_desc='	+encodeURIComponent(d2.value)+
						'&find_loc='	+encodeURIComponent(d2b.value);
				
				// xhr_with_disk_cache
				new AMT___requests_factory().xhr_with_disk_cache({
					
					URL: u,
					check_pre_write_to_disk: function(options) { // Return TRUE to write to disk. Return FALSE to not write to disk.
						var rs = options.response.responseText;
						
						if (rs.indexOf('Hey there! Before you continue, we just need to check that you\'re not a robot') != -1) {
							d1c.style.backgroundColor = 'yellow';
							window.open(options.response.finalUrl.replace('/snippet', ''));
							return false;
						} else if (rs.indexOf('Sorry, you\'re not allowed to access this page.')) {
							d1c.style.backgroundColor = 'yellow';
							return false;
						}
						else
							return true;
					},
					success_callback: function(options) {
						var rs = options.response.responseText;
						
						if (rs.indexOf('Hey there! Before you continue, we just need to check that you\'re not a robot') != -1) {
							d1c.style.backgroundColor = 'blue';
							window.open(options.response.finalUrl.replace('/snippet', ''));
							return;
						}
						
						yelp_success(options.response);
					}
					
				});
				return;
			}
			/**
			 * function yelp_api
			 *
			 * e.g. http://api.yelp.com/v2/search/?term=home depot&location=San Francisco, CA&limit=10&radius_filter=30000
			 * TODO: Error message for 25,000 API limit?
			 * 
			 * Uses ll.lat and ll.lng
			 */
			function yelp_api() {
				 var auth = {
					//
					// Update with your auth tokens.
					//
					consumer_API_KEY_REDACTED_,
					consumer_API_KEY_REDACTED_,
					access_API_KEY_REDACTED_,
					accessToken_API_KEY_REDACTED_,
					serviceProvider : {
						signatureMethod : "HMAC-SHA1"
					}
				};
				var terms = d2.value;
				var near = d2b.value;//'San+Francisco';
				var accessor = {
					consumerSecret : auth.consumerSecret,
					tokenSecret : auth.accessTokenSecret
				};
				parameters = [];
				parameters.push(['term', terms]);
				parameters.push(['location', near]);
				//~ parameters.push(['cll', ll.lat + ',' + ll.lng]); // xxxxx
				parameters.push(['oauth_consumer_key', auth.consumerKey]);
				parameters.push(['oauth_consumer_secret', auth.consumerSecret]);
				parameters.push(['oauth_token', auth.accessToken]);
				parameters.push(['oauth_signature_method', 'HMAC-SHA1']);
				var message = {
					'action' : 'http://api.yelp.com/v2/search',
					'method' : 'GET',
					'parameters' : parameters
				};

				OAuth.setTimestampAndNonce(message);
				OAuth.SignatureMethod.sign(message, accessor);

				var parameterMap = OAuth.getParameterMap(message.parameters);
				var p = [];
				for (var i in parameterMap) {
					p.push(i + '=' + encodeURIComponent(parameterMap[i]));
				}
				p = '?' + p.join('&');
				
				new AMT___requests_factory().xhr_with_disk_cache({
					URL: 'http://api.yelp.com/v2/search' + p,
					filename: new AMT___requests_factory().md5('http://api.yelp.com/v2/search|' + d2.value + '|' + d2b.value), // Static file name
					check_pre_write_to_disk: function(options) { // Return TRUE to write to disk. Return FALSE to not write to disk.
						var rs = options.response.responseText;
						if  (
							rs.indexOf('we just need to check that you\'re not a robot') != -1 ||
							rs.indexOf('"text": "Signature was invalid"') != -1
							)
						{
							d1c.style.backgroundColor = 'yellow';
							return false;
						}
						else
							return true;
					},
					success_callback: function(options) {
						var rs = options.response.responseText;
						yelp_api_success(options.response);
					}
				});
			}
			function yelp_api_success(response) { // OUT = d1c
				d1c.innerHTML = '';
				d1c.appendChild(
					d2.value.div( {'style':'border-bottom:4px solid teal;width:100%;'} )
				);
				var rs = response.responseText;
				rs = JSON.parse(rs); //{"businesses": [{},{},{}]}
				if (!rs.businesses || rs.businesses.length == 0) {
					d1c.appendChild(document.createTextNode('0'));
					// DO RIGHT
					// TURN OFF FOR NOW........
					//yelp();
					o.stats.yelp_search_complete = true;
					check_if_yp_init();
					return;
				}
				// Loop
				var b = rs.businesses;
				var auto_found = false;
				var found_close_enough_street = false;
				var found_one = false;
				for (var i in b) {
					var dist;
					if 	(
						b[i].location &&
						b[i].location.coordinate
						)
					{
						dist = MT___lat_lng_distance(//MT___lat_lng_distance(lat1, lon1, lat2, lon2)  MILES
							b[i].location.coordinate.latitude*1,
							b[i].location.coordinate.longitude*1,
							ll.lat*1,
							ll.lng*1
						);
						dist = Math.ceil(dist); // e.g. 3.9 is 4. 
					}
					var bgc = (dist > 4) ? 'background-color:aqua;' : '';
					
					// Check skip
					if (!b[i].phone) continue;
					var tmp_phone = b[i].phone.replace(/[^\d]/g, '');
					check_accept(b[i].name, tmp_phone);
					var tmp_addr = (
						b[i].location.address != '' ?
						b[i].location.address + ',' + b[i].location.city + ',' + b[i].location.state_code :
						b[i].location.display_address
					);
					// Check skip, state
					if (o.state_abbr) { // Has State Abbr
						if (tmp_addr.indexOf(o.state_abbr) == -1) {
							continue; // Skip...
						}
					}
					
					// Still here?
					found_one = true;
					// Div
					var d = document.createElement('div');
					d.setAttribute('style','border-bottom:1px solid #a2a2a2;'+bgc);
					d.className = 'exe';
					d.ypurl = b[i].url;
					d.yphone = b[i].phone.replace(/[^\d]/g, '');
					d.yhref = b[i].url;
					d1c.appendChild(d);
					d.innerHTML =
						MT__bold(b[i].name, o.name_arr) + '<br>' +
						'P:'+(b[i].display_phone ? b[i].display_phone.replace(/^\+1-/, '') : '')+'<br>'+
						'A:'+ tmp_addr + '<br>' +
						'D:'+(dist ? dist + 'mi' : '');
					d.onclick = function() {
						this.style.backgroundColor = 'teal';
						set_divs_clicked(this.yphone); // SET ALL WITH SAME PHONE AS TEAL
						q.value = this.yphone;
						if (q2)
							q2.value = this.yhref;
						if  (
							o.bad_phones_obj.hasOwnProperty( this.yphone ) ||
							this.yphone.length != 10 ||
							!/^https?:\/\/[^\/]+\/[^$]+$/.exec( this.yhref )
							)
						{
							d2.value = 'bad phone!';
							d2.style.backgroundColor = 'LightGreen';
							q.style.border = '4px solid teal';
							return;
						}
						
						// Here?
						doSubmit();
					}
					
					//~ var ypnm_cln = b[i].name.clean_str_to_auto();
					//~ var ypad_cln = fmt_address_match.clean_str_to_auto();
					//~ // Auto found?
					//~ if  (
						//~ !auto_found &&
						//~ o.comp_cln == ypnm_cln &&
						//~ o.addr_cln == ypad_cln &&
						//~ o.comp_cln.length > 4 &&
						//~ o.addr_cln.length > 4
						//~ )
					//~ {
						//~ d.click();
						//~ auto_found = true;
					//~ }
				}
				if (d1c.innerHTML != '' && found_one) {
					var d = document.createElement('div');
					d.setAttribute('style','height:2000px;');
					d1c.appendChild(d);
				} else {
					d1c.appendChild(
						'0'.div()
					);
				}
				// 
				o.stats.yelp_search_complete = true;
				check_if_yp_init();
			}
