		function James_Deetz_radaris() {
			d1b.innerHTML = '';
			
			var x;
			var y = d2.value;
			x = /^(\w+) \w{1} (\w+)$/.exec(y);
			if (x) {
				x[3] = x[2];
			} else {
				x = /^(\w+) (\w+)$/.exec(y);
				if (x) {
					
				} else
					return;
			}
			
			// x1, x2
			var z = '';
			for (var state_abbr in MT___states) {
				if (state_abbr == state) {
					z = encodeURIComponent(MT___states[state_abbr]);
					break;
				}
			}// else
			//	z = '';
			
			GM_xmlhttpRequest({
				method: "GET",
				url: 'http://radaris.com/ng/search?ff='+encodeURIComponent(x[1])+'&fl='+encodeURIComponent(x[2])+'&fs='+z+'&fc='+city,
				onload: function(response) {
					var rs = response.responseText;
					
					if (response.status != 200) {
						d1b.innerHTML = response.status;
						return;
					}
					
					var r;
					
					r = /<header><h1>((.|\s)*?(?=<\/h1><\/header>|$)|$)/.exec(rs);
					if (r) {
						d1b.innerHTML = r[1]+'<hr>';
					} else
						d1b.innerHTML = 'x<hr>';
					
					r = /<p class="name">((.|\s)*?(?=<p class="name">|<\/div>    <\/div>|$)|$)/g;
					var m;
					var c = 0;
					while (m = r.exec(rs)) {
						var r2;
						
						// /~Mark-Rydberg/154302563
						r2 = /<a href="([^"]+)" rel="nofollow" class="btn-profile">view details<\/a>/.exec(m[1]);
						if (r2) {
							r2 = 'http://radaris.com'+r2[1];
						} else
							r2 = 'x';
						
						m[1] = m[1].replace(/<a href="([^"]+)" rel="nofollow" class="btn-profile">view details<\/a>/, '');
						//m[1] = m[1].replace(/<\/[^>]*>/g, '');
						//m[1] = m[1].replace(/<[^>]*>/g, '<br>');
						m[1] = m[1].replace(/<\/?a[^>]*>/gi, '<br>');
						m[1] = m[1].replace(/Lived in:/g, '<br>Lived in:');
						m[1] = m[1].replace(/Known also:/g, '<br>Known also:');
						m[1] = m[1].replace(/Related to:/g, '<br>Related to:');
						
						d1b.innerHTML += '\
							<input type="button" value="'+r2+'" class="exe-radaris">\
							<br>\
							'+m[1]+'\
							<hr>\
						';
						
						if (c == 0) {
							var x = d1b.getElementsByClassName('exe-radaris');
							x = x[x.length -1];
							x.style.backgroundColor = 'LightGreen';
							James_Deetz_radaris_profile(x.value);
						}
						c++;
					}
					if (d1b.innerHTML != '') {
						d1b.innerHTML += '<div style="height:1200px;"></div>';
					}
					
					var x = document.getElementsByClassName('exe-radaris');
					for (var i in x) {
						x[i].onclick = function() {
							if (this.value != 'x') {
								this.style.backgroundColor = 'LightGreen';
								James_Deetz_radaris_profile(this.value);
							}
						}
					}
				}
			});
		}
