		function Paul_Graham_biz__complete(rs) {
			
			if (rs.length == 0) {
				d1.innerHTML = '<b>0<b>';
				Paul_Graham_biz__general_search_init();
				
				//~ if (AMT__Global_Vars.isPreview) {
					//~ AMT___Floater.skip();
				//~ }
				return;
			} else {
				d1.innerHTML = '';
				if (AMT__Global_Vars.isPreview) {
					AMT___Floater.accept();
					return;
				}
			}
			
			console.log(rs);
			
			for (var i in rs) {
				
				var short;
				var extra = '';
				var isMatch;
				
				var comp = /^((.|\s)*?(?=\| *LinkedIn|$)|$)/i.exec(rs[i][1]);
				//~ var comp = /^([^\|]+)\| *LinkedIn/i.exec(rs[i][1]);
				if (comp) {
					comp = __js_clean_html_str(comp[1].replace(/<[^>]*>/g, '')).trim();
					comp = comp.replace(/\s+/g, ' ');
					comp = comp.replace(/ *\| *LinkedIn[^$]*$/gi, '').trim();
					comp = comp.replace(/ *- *Company *Profile$/gi, '').trim();
					comp = comp.replace(/ *- *Company *Profile *on *LinkedIn[^$]*$/gi, '').trim();
				} else {
					comp = '';
				}
				console.log('comp:'+comp);
				
				var x = /^(https?:\/\/\w+\.linkedin\.com\/company\/[^\/]+)([^$]*)/.exec(rs[i][0]);
				if (x) {
					short = (x) ? x[1] : rs[i][0];
					if (x[2])
						extra = '<b>' +x[2]+ '</b><br>';
				} else {
					short = rs[i][0];
				}
				
				var d = document.createElement('div');
				d.setAttribute('style','border-bottom:1px solid #a2a2a2;');
				d.comp = comp;
				d.className = 'div-yahoo';
				d.onclick = function() {
					this.style.backgroundColor = 'LightGreen';
					document.getElementById('company_name').value = this.comp;
					if (this.comp.length >= 3)
						doSubmit();
				}
				d.innerHTML = '<u>' + MT__bold(comp, o.comp_arr) + '</u><br>' + short + '<br>' + rs[i][1]; //extra
				
				// ...
				d.appendChild(document.createElement('br'));
				
				// ...
				var a = document.createElement('a');
				a.href = rs[i][0];
				a.innerText = 'L';
				a.setAttribute('style','font-weight:bold;zoom:1.4;');
				a.onclick = function(e) {
					this.style.backgroundColor = 'LightGreen';
					window.open(this.href, 'new');
					e.stopPropagation();
					e.preventDefault();
					return false;
				}
				d.appendChild(a);
				
				//
				d1.appendChild(d);
				
				isMatch = (new RegExp('<b>Website<\\/b> *http:\/\/(www\\.|)<b>'+__js_escape_regEx(o.comp)+'<\\/b>\\/* ', 'i')).exec(rs[i][1]);
				console.log('isMatch:'+isMatch);
				if (isMatch) {
					d.style.border = '6px solid LightGreen';
				}
				
				//
				//"Canada Lithium | LinkedIn    www.<b>linkedin.com/company/</b>canada-lithium &nbsp;&nbsp;&nbsp; Cached  <b>Website</b> http://www.<b>canadalithium.com</b> Industry Mining &amp; Metals. This LinkedIn Company Profile was created by LinkedIn and is about Canada Lithium.  "
				if  (
					!auto &&
					i == 0 &&
					isMatch &&
					comp.toLowerCase().replace(/[^\w\d]/g, '') == o.comp_cln &&
					o.comp_cln.length >= 6 &&
					comp.length <= 60
					)
				{
					d.click();
				}
				
			}
			
			// ...
			var d = document.createElement('div');
			d.setAttribute('style','height:1600px;');
			d1.appendChild(d);
		}
