		function kyle_morris_linkedin_biz__SP_complete(rs) {
			if (rs.length == 0) {
				var v = '0\n'+d2.value;
				
				d1c.innerText = v;
				
				// 0 Results???
				// Both sides
				if (d1.innerText == v && /\.\w+$/.exec(d2.value)) {
					d2.value = d2.value.replace(/\.\w+$/, '');
					kyle_morris_linkedin_biz__init();
					kyle_morris_linkedin_biz__SP_init();
				} else {
					d2.style.border = '2px solid blue';
				}
				return;
			}
			for (var i in rs) {
				
				// Get rid of extraneous text on links.
				// E.g. /company/389583?blahblbahalbahlabhlbhalhb = /company/389583.
				var short;
				var extra = '';
				var x = /^(https?:\/\/\w+\.linkedin\.com\/company\/[^\/]+)([^$]*)/.exec(rs[i][0]);
				if (x) {
					short = (x) ? x[1] : rs[i][0];
					short = short.replace(/^https?:\/\/\w+\./i, 'http://www.')
					if (x[2])
						extra = '<b>' +x[2]+ '</b><br>';
				} else {
					short = rs[i][0].replace(/^https?:\/\/\w+\./i, 'http://www.');
				}
				
				// Get rid of extraneous rs[i][1] BODY
				rs[i][1] = rs[i][1].replace(/(http:\/\/|)\w+\.linkedin\.[^\/]+\/ *company/, '');
				
				var d = document.createElement('div');
				d.setAttribute('style','border-bottom:1px solid #a2a2a2;cursor:pointer;');
				d.y_url = short;
				d.className = short;
				//~ d.className = 'exe';
				d.onclick = function() {
					//~ this.style.backgroundColor = 'LightGreen';
					//
					var el = document.getElementsByClassName(this.className);
					for (var i in el) {
						if (i == 'length') break;
						el[i].style.border = '2px solid LightGreen';
						el[i].style.backgroundColor = 'aqua';
					}
					// ...
					document.getElementById('web_url').value = this.y_url;
					if (/^http:\/\/www\.linkedin\.com\/company\/[^\/$]+/.exec(this.y_url)) {
						new AMT___core_factory().nextTab();
						doSubmit();
					}
				}
				d.innerHTML = short + '<br>' + extra + MT__bold( rs[i][1], o.bold_array ); //.replace(/<\/?b>/g, '')
				d1c.appendChild(d);
				
				// mouseover
				d.onmouseover = function() {
					var el = document.getElementsByClassName(this.className);
					for (var i in el) {
						if (i == 'length') break;
						el[i].style.backgroundColor = 'LightGreen';
					}
				}
				// mouseout
				d.onmouseout = function() {
					var el = document.getElementsByClassName(this.className);
					for (var i in el) {
						if (i == 'length') break;
						el[i].style.backgroundColor = '';
					}
				}
				
				// ...
				var a = document.createElement('a');
				a.href = rs[i][0];
				a.innerText = 'L';
				a.setAttribute('style','font-weight:bold;zoom:1.4;');
				a.onclick = function(e) {
					this.style.backgroundColor = 'LightGreen';
					window.open(this.href, 'new');
					e.stopPropagation();
					e.preventDefault();
					return false;
				}
				d.appendChild(a);
			}
		}
