		function Matthew_Kennedy_LinkedInProfileAndEmployees__google__2 () {
			
			var url = 'https://www.google.com/search?q='+encodeURIComponent('site:linkedin.com/company/ ' + d2.value);
			d1a2.innerText = '';
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: url,
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status > 200) {
						d1b.style.backgroundColor = 'pink';
						return;
					}
					
					var r;
					r = /<h3 class="r"><a href="([^"]+)[^>]*>((.|\s)*?(?=<!--n-->|$)|$)/g;
					var count = 0;
					if (r.exec(rs)) {
						r.lastIndex = 0;
						var c = 1;
						var sbm = true;
						while (m = r.exec(rs)) {
							
							m[1] = __js_clean_html_str(m[1]);
							
							// replace "harm your comp."
							m[1] = m[1].replace(/^\/interstitial\?url=/, '');
							
							// google.com
							if (/^\//i.exec(m[1]))
								continue;
							
							//~ if (!/https?:\/\/[^\/]{6,}/.exec(m[1])) {
								//~ //sbm = false;
							//~ }
							
							var li = m[1].replace(/^(http:\/\/[^\/]+\/company\/[^\/]+)[\d\D]*/, '$1');
							
							var x = document.createElement('div');
							x.setAttribute('style', 'border-bottom: 1px solid #a2a2a2;cursor:pointer;');
							x.id = li;
							x.onclick = function() {
								this.style.backgroundColor = 'LightGreen';
								//Matthew_Kennedy_LinkedInProfileAndEmployees__prof__2(this.id);
								Matthew_Kennedy_LinkedInProfileAndEmployees_realCount__google_prof(this.id);
							}
							
							x.appendChild(document.createTextNode(m[1]));
							x.appendChild(document.createElement('br'));
							x.appendChild(document.createTextNode(
								m[2].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ')
							));
							
							d1a2.appendChild(x);
							
							c++;
							
							if (c >= 8) // 1...7
								break;
						}
					}
				}
			});
		}
