		function Steven_James_Moody_linkedin__prof(u) {
			//alert('test');
			var q = document.getElementById('linkedinurl');
			q.style.border = '2px dashed blue';
			
			d1a2.innerHTML = '';
			
			GM_xmlhttpRequest({
				method: "GET",
				url: u,
				onload: function(response) {
					var rs = response.responseText;
					
					if (response.status != 200) {
						d1.innerHTML = response.status;
						return;
					}
					
					// dashes
					rs = rs.replace(/\\u002d/g, '-');
					
					var q = document.getElementById('linkedinurl');
					
					// url
					r = /"public_url":\{("deferImg":[^,]*,|)"canonicalUrlToShow":"[^"]+","canonicalUrl":"([^"]+)","showPublicProfileURL":true\}/.exec(rs);
					if (r) {
						q.value = r[2];
						q.style.border = '';
						//q.style.border = '2px solid lime';
						if (/^https?:\/\/www\.linkedin\.com\//.exec(r[2]) && !/\\u[\d\w]+/.exec(r[2])) {
							
							// only submit if filled in
							var sbm = true;
							for (var i in allq) {
								if (allq[i].value.trim().length < 2) {
									sbm = false;
									break;
								}
							}
							//if (sbm)
							//	doSubmit();
						}
						u = r[2];
					} else {
						q.value = u;
						q.style.border = '4px dashed blue';
					}
					
					// other
					d1a2.innerHTML = '';
					
					//topcard
					r = /<code id="top_card-content" style="display:none;"><!--\{((.|\s)*?(?=\}--><\/code>|$)|$)/.exec(rs);
					if (r) {
						r = JSON.parse('{'+r[1]+'}');
						r = r.content;
					}
					
					// "BG CONTENT"
					var r2 = /<code id="profile_v2_background-content" style="display:none;"><!--\{((.|\s)*?(?=\}--><\/code>|$)|$)/.exec(rs);
					if (r2) {
						r = JSON.parse('{'+r2[1]+'}');
						r = r.content;
					} else {
						
					}
					
					console.log(r);
					// now?
					if (r) {
						//experience
						var found = false;
						try {
							if (r.Experience.positionsMpr.positions.length) {
								for (var i in r.Experience.positionsMpr.positions) {
									var x = r.Experience.positionsMpr.positions[i];
									console.log(x);
									
									
																		
									var pt,pc;
									pt = __js_clean_html_str(x.title_highlight.replace(/<[^>]*>/g, ''));
									pc = __js_clean_html_str(x.companyName.replace(/<[^>]*>/g, ''));
										
									
									var div = document.createElement('div');
									div.setAttribute('style','border-bottom:1px solid #a2a2a2;cursor:pointer;');
									div.bizProfUrl = 'http://www.linkedIn.com' + x.biz_prof;
									div.onclick = function() {
										this.style.backgroundColor = 'LightGreen';
										allq[1].value = this.title;
										allq[2].value = this.comp;
										allq[1].focus();
									
										GM_xmlhttpRequest({
												method: "GET",
												url: this.bizProfUrl,
												onload: function(response) {
													var rs = response.responseText;
													
													if (response.status != 200) {
														d1.innerHTML = response.status;
														return;
													}
													//http%3A%2F%2Fwww%2Ewalmart%2Ecom
													
													//a href="https://www.linkedin.com/redirect?url=http%3A%2F%2Fwww%2Ewalmart%2Ecom&amp;urlhash=ZjHg" target="_blank" title="New window will open"
													var bizLinkReg = /a href="https:\/\/www\.linkedin\.com\/redirect\?url=([^&]+)&[^"]+" target="_blank" title="New window will open"/; 
													var bizLink = bizLinkReg.exec(rs);
													if(!bizLink)
													{
														//There appears to be no biz link
														bizLink = 'NA';
													}
													else
													{
														bizLink = __js_clean_html_str(bizLink[1]);
														bizLink = decodeURIComponent(bizLink);
													}
													document.getElementById('newcompanydomain').value = bizLink;
													//alert('made it here');
												}
											});
					
										
										if  (
											this.comp.length  > 1 &&
											this.title.length > 1 &&
											allq[0].style.border == ''
											)
										{
											//doSubmit();
										}
									}
									div.innerText = pt + "\n" + pc;
									div.title = pt;
									div.comp  = pc;
									div.isPresent = false;
									if (x.startdate_iso || x.enddate_iso) {
										if (x.startdate_iso) {
											div.innerText += "\n" + 'S:' + x.startdate_iso;
										}
										if (x.enddate_iso) {
											div.innerText += "\n" + 'E:' + x.enddate_iso;
										}
									} else {
										div.style.backgroundColor = 'orange';
										div.isPresent = true;
									}
									if (x.present && x.present == 'Present') {
										div.style.border = '4px solid teal';
										div.isPresent = true;
									}
									//else if (div.isPresent
									//	div.isPresent = false;
									if  (
										div.isPresent &&
										allq[1].value == div.title &&
										allq[2].value == div.comp &&
										div.comp.length  > 1 &&
										div.title.length > 1 &&
										allq[0].value.trim() != '' &&
										allq[0].style.border == ''
										)
									{
										
										//doSubmit();
									}
									d1a2.appendChild(div);
								}
							} else {
								//
							}
							d1a2.appendChild(document.createElement('hr'));
						}
						catch(e) {
							//
						}
					}
				}
			});
		}
