						if (rs.indexOf(r) != -1) {
							
							document.body.style.backgroundColor = 'LightGreen';
							document.getElementById('Q5LinktoWebpage').checked = true;
							doSubmit();
							
							return;
						} else {
							
							document.getElementById('Q1LinktoWebpage').checked = true;
							
						}
						
						
						//ALLAN ZENDEL
