		function Andrew_Cotter_LinkedIn_prof() {
			
			// Yahoo
			var u = 'http://search.yahoo.com/search?p=%2B'+encodeURIComponent('site:linkedin.com '+d2c.value); //%2B
			var out = d1a2;
			out.innerHTML = '';
			
			// select field
			var d = document.createElement('select');
			d.setAttribute('multiple', true);
			d.setAttribute('class', 'exe-AC-select');
			for (var i = 1; i<=5; i++) {
				if (i == 1)
					d.innerHTML += '<option value="'+i+'" selected>'+i+'</option>';
				else
					d.innerHTML += '<option value="'+i+'">'+i+'</option>';
			}
			out.appendChild(d);
			
			var __d2c_loc = /^"[^"]+" "([^"]+)"$/.exec(d2c.value);
			if (__d2c_loc)
				__d2c_loc = __d2c_loc[1].trim();
			else
				__d2c_loc = '';
				
			GM_xmlhttpRequest({
				method: 'GET',
				url: u,
				onload: function (response) {
					var rs=response.responseText;
					
					var rg = /yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g;
					
					if (rg.exec(rs) && rs.indexOf('Including results for') == -1) {
						rg.lastIndex = 0;
						rg=/yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g; // li
						var count = 0;
						var x, match;
						
						var r, m;
						var nm;
						var bgc;
						var found = false;
						while (match = rg.exec(rs)) {
							if (count >= 10)
								break;
							
							match[1] = decodeURIComponent(match[1]);
							
							if (match[1].indexOf('/dir/') != -1) continue;
							if (match[1].indexOf('/title/') != -1) continue;
							if (match[1].indexOf('/in/updates?') != -1) continue;
							
							//domain = match[1].replace(/^(http:\/\/[^\/]+)\/[^$]*$/, '$1');
							
							match[2] = match[2].replace(/<b>/g, '`');
							match[2] = match[2].replace(/<\/b>/g, '``');
							
							//match[2] = match[2].replace(/<\/?b>/g, '');
							
							match[2] = match[2].replace(/<[^>]+>/g, ' ');
							match[2] = match[2].replace(/[<>]/g, '');
							match[2] = match[2].replace(/``/g, '</b>');
							match[2] = match[2].replace(/`/g, '<b>');
							
							nm = /^([^\|]+)/.exec(match[2].replace(/<[^>]+>/g, '').trim());
							//var name_length = 0;
							//console.log(nm);
							if (nm) {
								nm = nm[1].replace(/ -[^$]*/, '');//- Canada | LinkedIn
								nm = nm.trim();
							} else nm = '';
							//if (/Cached [^,\.]+,/.exec(match[2])) {
							//	bgc = '#acafac';
							//} else
								bgc = '#eee';
								
							out.innerHTML += '\
								<p style="border-bottom:1px solid teal;background-color:'+bgc+'">\
								<input type="button" value="'+match[1]+'" class="exe-yahoo" style="width:auto;" > \
								<a href="'+match[1]+'" target="_blank">link</a> \
								<br ><input type="button" value="'+nm+'" class="nm">\
								<br >'+match[2]+'\
								</p>';
							
							if (!found && bgc == '#eee' && count <= 1) { //1st 2
								//found = true;
								
								var x = document.getElementsByClassName('exe-yahoo');
								x = x[x.length -1]; // last
								
								var y = x.parentNode.getElementsByClassName('nm');
								
								// Cached name[1] name[2]. Job title.
								var ma = match[2].replace(/<\/?b>/g, '');
								ma = __js_clean_html_str(ma);
								ma = ma.replace(/View [^']+'s professional profile on LinkedIn\./g, '');
								ma = ma.replace(/\s+/g, ' ');
								console.log(ma);
								
								var auto = new RegExp( // name\.* *Title
									//'Cached *'+
									'(Cached|) *'+
									__js_escape_regEx(__js_clean_html_str(y[0].value))+ // first+last
									'\\.? *'+ // period or spaces
									__js_escape_regEx(JOB_TITLE)+ // title
									' Location '+
									'((.|\\s)*?(?='+__js_escape_regEx(__js_clean_html_str(__d2c_loc))+'|$)|$)'
									//__js_clean_html_str(__d2c_loc)
									, 'i'
								);
								console.log(auto);
								auto = auto.exec(ma);
								
								if (auto) {
									found = true;
									
									x.style.backgroundColor = 'LightGreen';
									
								}
							}
							count++;
						}
						
						if (count > 0) {
							out.innerHTML += '<div style="height:1000px;">&nbsp;</div>';
						}
						
						var x = document.getElementsByClassName('exe-yahoo');
						for (var i in x) {
							x[i].onclick = function() {
								var x = this.parentNode.getElementsByClassName('nm');
								this.style.backgroundColor = 'LightGreen';
								
								x = x[0].value;
								var id = document.getElementsByClassName('exe-AC-select')[0].value;
								var i = document.getElementById('Q'+id)
								i.value = x;
								i.focus();
							}
						}
					} else
						out.innerHTML = '0 ' + d2c.value;
				}
			});
		}
