			//url+= '&lastName='+encodeURIComponent(d2b.value.trim());
			url+= '?company='+encodeURIComponent(d2.value.trim());
			url+= '&companyScope=C'; // scope is current company rather than current/past or past
			url+= '&keywords='+encodeURIComponent(d2b.value.trim());
