	s = 'Please report the average rating and number of ratings for exactly those 10 restaurants that appear once the website has finished loading. The list shown on the website should start with ';
	if (ih.indexOf(s) != -1) {
		GM_addStyle('body,p,h2,h1,h3,h4,ul,li,form,input,span,p,div,textarea {margin:0;padding:0;font-size:12px;}');
		GM_addStyle('body {width:100%;margin-top:0px;}');
		
		var a = document.getElementsByTagName('a')[0].href;
		//http://www.yelp.com/search?find_desc=restaurants&find_loc=Berkeley%2C+CA&ns=1#start=1510
		a = a.replace('http://www.yelp.com/search', 'http://www.yelp.com/search/snippet');
		a = a.replace('#start', '&start');
		
		GM_xmlhttpRequest({
			method: "GET",
			url: a,
			onload: function(response) {
				var rs = response.responseText;
				
				if (response.status != 200) return;
				
				rs = JSON.parse(rs);
				if (!rs.search_results) return;
				rs = rs.search_results;
				
				var r;
				r = /<img alt="([\d\.]+) star rating" class="offscreen" height="\d+" src="[^"]+" width="\d+">[\r\n\t\s]+<\/i>[\r\n\t\s]+<\/div>[\r\n\t\s]+<span class="review-count rating-qualifier">[\r\n\t\s]+([\d,]+) review/g;
				if ((rs.match(r)).length != 10) {
					console.log('#'+(rs.match(r)).length);
					return;
				}
				//here?
				// 0-8
				var m;
				var c = 1;
				var i;
				var sbm = true;
				while (m = r.exec(rs)) {
					switch(m[1]) {
						case '1.0':
							i = 0;
							break;
						case '1.5':
							i = 1;
							break;
						case '2.0':
							i = 2;
							break;
						case '2.5':
							i = 3;
							break;
						case '3.0':
							i = 4;
							break;
						case '3.5':
							i = 5;
							break;
						case '4.0':
							i = 6;
							break;
						case '4.5':
							i = 7;
							break;
						case '5.0':
							i = 8;
							break;
						default:
							sbm = false;
					}
					//document.getElementsByName('R'+c)[0].value = i;
					document.getElementsByName('R'+c)[0].selectedIndex = i;
					document.getElementsByName('nr_ratings'+c)[0].value = m[2];
					c++;
				}
				if (sbm) {
					doSubmit();
				}
			}
		});
	}
	
