	function sam_molyneux_journals_yahoo() {
		//><img src='http://ts
		var url;
		if (FIRST_RUN) {
			FIRST_RUN = false;
			url = 'http://images.search.yahoo.com/search/images?p='+encodeURIComponent(di.value+' "journal"')+'&ei=utf-8&fr=sfp-img&fr2=&y=Search';
		} else
			url = 'http://images.search.yahoo.com/search/images?p='+encodeURIComponent(di.value)+'&ei=utf-8&fr=sfp-img&fr2=&y=Search';
		GM_xmlhttpRequest({
			method: 'GET',
			url: url,
			onload: function (response) {
				var rs = response.responseText;
				
				var r, m, full = [], c = 0;
				
				// full
				// "iurl":"
				r = /"iurl":"([^"]+)/g;
				if (r.exec(rs)) {
					r.lastIndex = 0;
					while (m = r.exec(rs)) {
						full[c] = m[1].replace(/\\\//g, '/');
						c++;
					}
				}
				
				var r, m, c = 0;
				// thumb
				r = /><img src='http:\/\/ts([^']+)/g;
				if (r.exec(rs)) {
					r.lastIndex = 0;
					while (m = r.exec(rs)) {
						if (c >= 4) break;
						
						f = (full[c]) ? full[c] : '';
						d1b.innerHTML += '<img src="http://ts'+m[1]+'" id="'+f+'" class="exe-yahoo" style="border:1px solid lime;height:160px;">';
						c++;
					}
					
					sam_molyneux_journals_update();
				} else
					d1b.innerHTML = '0';
			}
		});
	}
