		function michael_curylo_theater_google() {
			// 0,0 20000000 = world search =~ 12,000 miles
			// 2,000,000 =~ 1200 miles
			// London 51.5072° N, 0.1275° W
			// 40k meters = 25 miles
			//
			d1.innerHTML = '';
			
			//var u = 'https://maps.googleapis.com/maps/api/place/autocomplete/json?input='+
			var u = 'https://maps.googleapis.com/maps/api/place/nearbysearch/json?keyword='+
				encodeURIComponent(d2.value)+
				'&types=establishment&location='+loc.lat+','+loc.lng+'&radius=30000&sensor=false&key=_GOOGLE_API_KEY_REDACTED_';//&radius=2000
				
			//~ var u = 'https://maps.googleapis.com/maps/api/place/autocomplete/json?input='+
				//~ encodeURIComponent(d2.value)+
				//~ '&types=establishment&location=51.5072,0.1275&radius=20000&sensor=false&key=_GOOGLE_API_KEY_REDACTED_';
			
			GM_xmlhttpRequest({ // init
				method: "GET",
				url: MT___host + '/mturk/util.php?AMT__output_html_from_URL='+encodeURIComponent(u),
				//~ url: u,
				onload: function(response) {
					var rs = response.responseText;
					if (response.status != 200) return;
					
					rs = JSON.parse(rs);
					//console.log(rs);
					
					if (!rs.status || rs.status != 'OK' || !rs.results) {
						console.log(rs.status);
						d1.innerText = rs.status;
						//~ if (rs.status && rs.status == 'ZERO_RESULTS') {
							//~ if (AMT__Global_Vars.isPreview) {
								//~ AMT___Floater.skip();
							//~ }
						//~ }
						return;
					}
					
					rs = rs.results;
					
					console.log(rs);
					
					var div;
					var auto_submit = false;
					for (var i in rs) { //obj
						
						div = document.createElement('div');
						div.setAttribute('style','width:auto;text-align:left;border-bottom:2px solid teal;cursor:pointer;');
						div.setAttribute('id',JSON.stringify(rs[i]));
						div.addEventListener('click', function() {
							if  (
								this.style.backgroundColor != 'LightGreen' &&
								this.style.backgroundColor != 'rgb(245, 255, 250)' //
								)
							{
								this.style.backgroundColor = 'LightGreen';
								michael_curylo_theater_google__prof(this);
							} else {
								//
							}
						}, false);
						
						var is_theater_mall = false;
						if (rs[i].types) {
							for (var j = rs[i].types.length; j >= 0; j--) {
								if (rs[i].types[j] == 'movie_theater' || rs[i].types[j] == 'shopping_mall') {
									is_theater_mall = true;
								}
								
								if (rs[i].types[j] == 'establishment')
									delete rs[i].types[j];
								else if (rs[i].types[j] == 'movie_theater') {
									rs[i].types[j] = '<b>movie_theater</b>';
								}
							}
						}
						
						if (!is_theater_mall) {
							div.style.backgroundColor = 'aqua';
						}
						
						div.innerHTML = MT__bold(rs[i].name, NAME.split(' ')) + "<br>" + MT__bold(rs[i].vicinity, [CITY]);
						div.innerHTML+= (rs[i].types && rs[i].types.length) ? '<br>' + rs[i].types.join(',') : '';
						//div.innerText = rs[i].name + "\n" + MT__bold(rs[i].vicinity, [CITY]);
						d1.appendChild(div);
						
						// accept preview
						if (AMT__Global_Vars.isPreview) {
							AMT___Floater.accept();
							return;
						}
						
						if  (
							!auto_submit &&
							rs[i].name.toLowerCase() == NAME.toLowerCase() &&
							NAME.length >= 4 &&
							rs[i].vicinity.toLowerCase().indexOf(CITY.toLowerCase()) != -1 &&
							CITY.length >= 4
							)
						{
							auto_submit = true;
							div.click();
						}
					}
					
					//~ if (d1.innerText == '');
						//~ d1.innerText = '0';
					
					// here (and preview) = SKIP
					if (AMT__Global_Vars.isPreview) { //console.log('x');
						AMT___Floater.skip();
						return;
					}
					
					if (rs.length) {
						var div;
						div = document.createElement('div');
						div.setAttribute('style','height:1200px;');
						d1.appendChild(div);
					}
				}
			});
		}
		function michael_curylo_theater_google__prof(el) {
			// update button bgc
			//el.style.backgroundColor = 'MintCream';
			el.style.border = '2px solid teal';
			
			// obj
			var id = JSON.parse(el.id); // obj -> prediction
			
			var u = 'https://maps.googleapis.com/maps/api/place/details/json?reference='+
				id.reference+
				'&sensor=false&key=_GOOGLE_API_KEY_REDACTED_';
				
			GM_xmlhttpRequest({ // init
				method: "GET",
				url: MT___host + '/mturk/util.php?AMT__output_html_from_URL='+encodeURIComponent(u),
				//url: u,
				onload: function(response) {
					var rs = response.responseText;
					if (response.status != 200) return;
					
					var s = rs;
					
					rs = JSON.parse(rs);
					
					if (rs.status != 'OK' || !rs.result) {
						console.log(rs.status);
						return;
					}
					
					console.log(rs);
					
					rs = rs.result;
					
					var sbm = true;
					
					
					// zip?
					var found = false;
					for (var i in rs.address_components) {
						if (rs.address_components[i].types[0] == 'postal_code') {
							found = true;
							document.getElementsByName('Zip')[0].value = rs.address_components[i].long_name;
							if (rs.address_components[i].long_name.length < 5)
								sbm = false;
							break;
						}
					}
					if (!found)
						sbm = false;
					
					// str, city
					if (rs.adr_address) {
						var r2;
						
						r2 = /<span class="street-address">([^<]+)<\/span>/.exec(rs.adr_address);
						if (r2) {
							r2 = __js_clean_html_str(r2[1]).trim();
							document.getElementsByName('Street Address')[0].value = r2;
							if (r2.length < 4)
								sbm = false;
						} else
							sbm = false;
						
						r2 = /<span class="locality">([^<]+)<\/span>/.exec(rs.adr_address);
						if (r2) {
							r2 = __js_clean_html_str(r2[1]).trim();
							document.getElementsByName('City')[0].value = r2;
							if (r2.length < 2)
								sbm = false;
						} else
							sbm = false;
					} else
						sbm = false;
						
					console.log(sbm)
					if (sbm) {
						doSubmit();
					}
					
					// update button id/value
					//~ el.innerText += "\n"+rs.result.formatted_address;
					//~ el.id = s; //
					
					//~ var ph = rs.result.international_phone_number;
					//~ if (ph) {
						//~ document.getElementById('phone_new').value = ph;
						//~ if (/^\+\d{2} [\d ]+$/.exec(ph)) { // was \d{4} \d+$
							//~ document.getElementById('phone_new').style.border = '4px dotted blue';
							//~ doSubmit();
						//~ }
					//~ }
				}
			});
		}
