		function Tyler_Yamasaki_businesses_google__init_load_lat_lng() {
			MT___google_api_geocode('1, ' + CITY + ', ' + STATE, function(lat, lng) {
				LOC.lat = lat;
				LOC.lng = lng;
				Tyler_Yamasaki_businesses_google();
			}, false, true);
		}
		function Tyler_Yamasaki_businesses_google__init(start, callback) {
			
			var start = start;
			var callback = callback;
			
			GM_xmlhttpRequest({ // load the list of synonyms from the browser cache!
				method: "GET",
				url: AMT___POPUP___PROXY_REDACTED_ + '/mturk/.miscellaneous/AMT__Tyler_Yamasaki?'+Math.random()*10000,
				//~ url: u,
				onload: function(response) {
					var rs = response.responseText;
					if (response.status != 200) return;
					
					SYNONYMS = JSON.parse(rs);
					
					//~ console.log(SYNONYMS);
					//~ console.log(NAME);
					
					if (!SYNONYMS[NAME]) {
						SYNONYMS[NAME] = [];
					}
					
					if (!start && callback)
						callback();
					else {
						for (var i in SYNONYMS[NAME]) {
							SYNONYMS_TO_MATCH.push(SYNONYMS[NAME][i].replace(/[^\w\d]/g, '').toLowerCase());
						}
						SYNONYMS_TO_MATCH.push(NAME.replace(/[^\w\d]/g, '').toLowerCase());
						Tyler_Yamasaki_businesses_google__init_load_lat_lng();
					}
					
				}
			});
		}
		// WRITE TO FILE !
		function Tyler_Yamasaki_businesses_google__write_synonyms(el) {
			
			var el = el;
			
			Tyler_Yamasaki_businesses_google__init(false, function() {
				
				SYNONYMS[NAME].push(el.biz_name);
				
				//~ console.log(SYNONYMS[NAME]);
				
				var data; //, el = el;
				data = 'AMT__serverSide_write__value='+encodeURIComponent(JSON.stringify(SYNONYMS))+
					'&AMT__serverSide_write__folder=.miscellaneous'+
					'&AMT__serverSide_write__file=AMT__Tyler_Yamasaki';
					
				GM_xmlhttpRequest({ // load the list of synonyms from the browser cache!
					method: "POST",
					url: AMT___POPUP___PROXY_REDACTED_ + '/mturk/util.php',
					data: data,
					headers: {
						"Content-Type": "application/x-www-form-urlencoded"
					},
					//~ url: u,
					onload: function(response) {
						var rs = response.responseText;
						if (response.status != 200) return;
						
						el.style.backgroundColor = 'aqua';
						
						console.log(rs);
					}
				});
			});
		}
		// function Tyler_Yamasaki_businesses_google()
		function Tyler_Yamasaki_businesses_google() {
			
			d1.innerHTML = '';
			
			var u = 'https://maps.googleapis.com/maps/api/place/nearbysearch/json?keyword='+
				encodeURIComponent(d2.value)+
				'&types=establishment&location='+LOC.lat+','+LOC.lng+'&radius=30000&sensor=false&key=_GOOGLE_API_KEY_REDACTED_';
				
			//~ var u = 'https://maps.googleapis.com/maps/api/place/autocomplete/json?input='+
				//~ encodeURIComponent(d2.value)+
				//~ '&types=establishment&location='+LOC.lat+','+LOC.lng+'&radius=20000&sensor=false&key=_GOOGLE_API_KEY_REDACTED_';
			
			
			GM_xmlhttpRequest({ // init
				method: "GET",
				url: AMT___POPUP___PROXY_REDACTED_ + '/mturk/util.php?AMT__output_html_from_URL='+encodeURIComponent(u),
				//~ url: u,
				onload: function(response) {
					var rs = response.responseText;
					if (response.status != 200) return;
					
					rs = JSON.parse(rs);
					
					if (!rs.status || rs.status != 'OK' || !rs.results) {
						console.log(rs.status);
						d1.innerText = rs.status;
						if (AMT__Global_Vars.isPreview) { // SKIP_PAUSE !!
							AMT___Floater.skip();
						}
						return;
					}
					
					rs = rs.results;
					
					//console.log(rs);
					
					var div;
					var auto_submit = false;
					var clicked = false;
					for (var i in rs) { //obj
						
						// ONCLICK
						// ADD TO ACCEPTABLE LIST !!
						div = document.createElement('div');
						div.setAttribute('style','width:auto;text-align:left;border-bottom:2px solid teal;cursor:pointer;');
						div.biz_name = rs[i].name;
						div.addEventListener('click', function() {
							console.log(this);
							console.log(this.isInSynonymsArray);
							
							// push to SYNONYMS !!
							if (!this.isInSynonymsArray) {
								// WRITE TO FILE !
								Tyler_Yamasaki_businesses_google__write_synonyms(this);
							}
						}, false);
						if (__js_inarray(SYNONYMS[NAME], rs[i].name)) { // SHOW
							//~ console.log(NAME);
							//~ console.log(SYNONYMS[NAME]);
							//~ console.log(rs[i].name);
							div.style.backgroundColor = 'LightGreen';
							div.isInSynonymsArray = true;
						} else {
							div.isInSynonymsArray = false; // FALSE!
						}
						
						//~ var is_theater_mall = false;
						//~ if (rs[i].types) {
							//~ for (var j = rs[i].types.length; j >= 0; j--) {
								//~ if (rs[i].types[j] == 'movie_theater' || rs[i].types[j] == 'shopping_mall') {
									//~ is_theater_mall = true;
								//~ }
								//~ 
								//~ if (rs[i].types[j] == 'establishment')
									//~ delete rs[i].types[j];
								//~ else if (rs[i].types[j] == 'movie_theater') {
									//~ rs[i].types[j] = '<b>movie_theater</b>';
								//~ }
							//~ }
						//~ }
						//~ 
						//~ if (!is_theater_mall) {
							//~ div.style.backgroundColor = 'aqua';
						//~ }
						
						div.innerHTML = MT__bold(rs[i].name, NAME.split(' ')) + "<br>" + MT__bold(rs[i].vicinity, [CITY]);
						div.innerHTML+= (rs[i].types && rs[i].types.length) ? '<br>' + rs[i].types.join(',') : '';
						//div.innerText = rs[i].name + "\n" + MT__bold(rs[i].vicinity, [CITY]);
						d1.appendChild(div);
						
						/**
						 * @var found_name_match
						 */
						var tmp_name_to_match = rs[i].name.replace(/[^\w\d]/g, '').toLowerCase();
						var found_name_match = false;
						for (var j in SYNONYMS_TO_MATCH) {
							if (SYNONYMS_TO_MATCH[j] == tmp_name_to_match) {
								found_name_match = true;
								break;
							}
						}
						//~ console.log('tmp_name_to_match'+tmp_name_to_match);
						//~ console.log('found_name_match'+found_name_match);
						
						if  (
							
							// ENDS WITH ",CITY" -- COMMA PLUS CITY NAME
							REGEX_CITY_TO_MATCH.exec(rs[i].vicinity.replace(/[^\w\d,]/g, '').toLowerCase()) &&
							
							CITY_TO_MATCH.length >= 4 &&
							
							found_name_match &&
							NAME_TO_MATCH.length >= 4 &&
							//rs[i].name.replace(/[^\w\d]/g, '').toLowerCase() == NAME_TO_MATCH &&
							
							!clicked
							)
						{
							if (AMT__Global_Vars.isPreview) {
								AMT___Floater.accept();
								return;
							}
							
							// here !
							q[0].click();
							clicked = true;
							console.log(clicked);
						}
						
					}
					
					//~ if (d1.innerText == '');
						//~ d1.innerText = '0';
					
					// here (and preview) == SKIP
					if (AMT__Global_Vars.isPreview) { // SKIP_PAUSE !!
						AMT___Floater.skip();
						return;
					}
					
					if (rs.length) {
						var div;
						div = document.createElement('div');
						div.setAttribute('style','height:1200px;');
						d1.appendChild(div);
					}
				}
			});
		}
