	function Data_cleansing_highlightMatches(nameMatch,nameMatch2,color,trnum,tdnum)
	{
		if(!nameMatch || !nameMatch2) return;
		for(j in nameMatch2)
		{
			var c  =  nameMatch2[j].replace(/[^\w\d ]/g,"").toLowerCase();
			for(k in nameMatch)
			{
				if(nameMatch[k] == c)
				{
					//console.log(nameMatch[k]);
					//console.log(nameMatch2[j]);
					t[trnum].getElementsByTagName("td")[tdnum].innerHTML = Data_cleansing_sReplace(t[trnum].getElementsByTagName("td")[tdnum].innerHTML, nameMatch2[j], "<span style=\"color:" + color + "\"><b>"+nameMatch2[j]+"</b></span>");
				}
			}
		}
	}
	function Data_cleansing_sReplace(str, match, replace)
	{
		//console.log(str);
		//console.log(match);
		/*if(!match) return str;
		var sMatch = new RegExp("("+match+")","g");
		return str.replace(sMatch,replace);*/
		
		exit("last las name has a non-alphabetical _");
		
		return str.substring(0,str.indexOf(match))+"<b>"+replace+"</b>"+
			   str.substring(str.indexOf(match)+match.length,str.length);
	}
	

