		function jon_staff_clean_resolve(url) {
			
			var x = document.getElementsByTagName('input');
			var empty = false;
			for (var i in x) {
				if (!x[i]) continue;
				if (!x[i].type) continue;
				if (x[i].type != 'text') continue;
				if (x[i].value.trim() == '') {
					empty = true;
					break;
				}
			}
			if (!empty) {
				return;
			}
			
			console.log(links.length);
			if (links.length) {
				url = links.shift();
			} else if (!url) {
				return;
			}
			
			d2.style.border = '1px solid #ccc';
			
			jon_staff_clean_resolve_exec(url, true);
			
			if (links.length) {
				url = links.shift();
				jon_staff_clean_resolve_exec(url, false);
			}
		}
