		function jon_staff_google_com(u) {
			GM_xmlhttpRequest({ // init
				method: "GET",
				url: u,
				onload: function(response) {
					var rs = response.responseText;
					
					var r;
					
					r = /<h3 class="r"><a href="([^"]+)">/; //g
					
					if (!r.exec(rs))
						return;
					
					//r.lastIndex = 0;
					
					// get 1
					r = r.exec(rs);
					r = r[1];
					r = __js_clean_html_str(r);
					
					if (r.indexOf('/') === 0) {
						//https://www.google.com/shopping/product/2669905273433955152/online?hl=en&q=bicycle&num=100&sa=X&ei=WglNUuemK4fq8wT7zoGgDg&ved=0CDwQ6SQ
						//https://www.google.com/shopping/product/2669905273433955152?hl=en&q=bicycle&num=100&sa=X&ei=3whNUsOWGIPi8gSI6oHoCA&ved=0CJ4BEOUNMAA
						
						r = r.replace('?', '/online?');
						GM_xmlhttpRequest({ // init
							method: "GET",
							url: 'https://www.google.com'+r,
							onload: function(response) {
								var rs = response.responseText;
								
								r = /<span class="os-seller-name-primary"> <a href="([^"]+)">/g; //g
								
								if (!r.exec(rs))
									return;
								
								var m;
								var links = [];
								count = 0;
								while (m = r.exec(rs)) {
									//console.log(m[1]);return;
									if (!/&amp;adurl=([\d\D]+)$/.exec(m[1])) continue;
									m[1] = /&amp;adurl=([\d\D]+)$/.exec(m[1])[1];
									m[1] = __js_clean_html_str(m[1]);
									m[1] = decodeURIComponent(m[1]);
									
									if (!__js_inarray(links, m[1])) {
										links.push(m[1]);
										jon_staff_clean_resolve(m[1]);
										count++;
										if (count > 100)
											break;
									}// else
									//	
								}
							}
						});
						return;
					}return;
					
					
				}
			});
		}
		
