	// James Lovell
	// Get Data About a Company from LinkedIn
	// 
	// 
	var s = '<p>Enter the industry classification and number of employees&nbsp;as shown on LinkedIn profile for the provided company name.</p>\n\n<ul>\n	<li>Go to http://linkedin.com/</li>';
	if (ih.indexOf(s) != -1)
	{
		var run = function() {}
		run.prototype.f = function() {
			GM_addStyle('body,p,h2,h1,h3,h4,ul,li,form,input,span,p,div,textarea {margin:0;padding:0;font-size:12px;}');
			GM_addStyle('.panel-primary {position:absolute;top:1000px;}');
			//~ GM_addStyle('table {margin-bottom:-20px !important;}'); // make more space
			GM_addStyle('.container {margin:0 !important;padding:0 !important;position:absolute;top:1000px;}');// Move content to bottom...
			//~ GM_addStyle('.panel-primary {position:absolute;top:1000px;}');
			// Elements
			var td = document.getElementsByTagName('td');
			var o = {
				comp: td[1].innerText.trim(),
				boldArray: [],
				q: [
					document.getElementById('industry_classification'),
					document.getElementById('industry_classification_manual'),
					document.getElementById('number_of_employees')
				],
			}
			o.boldArray = o.comp.clean_string_to_array();
			console.log(o);
			/* BEGIN ITEMS */
			var d1 = document.createElement('div');
			d1.setAttribute('style',
				'position:absolute;top:0px;left:0%;width:100%;height:600px;overflow:auto;background-color:#eee;border:1px solid blue;'
			);
			document.body.appendChild(d1);
			/* END ITEMS */
			// innerHeight
			new AMT___core_factory().el_innerHeight({
				// This set the elements d1,d1b, and d1c
				// to fill up the whole window, minus their
				// distance from page top (top:XX pixels;).
				elements: [
					d1
				],
				offset: 0 // offset top
			});
			// create_dashboard_find_url
			AMT___items_factory.prototype.create_dashboard_find_url({
				bold_array: o.boldArray,
				search: {
					str_add_to_searches_hidden: ' site:linkedin.com/company/', // -site:linkedin.com/in/
				},
				searches: [
					o.comp,
					'"' + o.comp + '"',
					'"' + o.comp.split(' ').join('" "') + '"',
				],
				onclick_success: function(e) { // This is a button.onclick event.
					// this
					//~ console.log(this.full_url);
					// Scrape result
					li(this.full_url);
					this.style.backgroundColor = 'LightGreen';
				},
				search_results: {
					use_domain_only: true,
					use_full_urls: true,
					//~ bold: {
						//~ black: o.boldArray,
						//~ blue: [],// o.address.clean_string_to_array(), // Too much...
						//~ brown: o.addr_arr,
					//~ },
					//~ url_modifier_callback: function(url) { // Add @ symbol
						//~ url = '@' + url;
						//~ return url;
					//~ },
				},
				//~ out_element: o.q[0],
				parent: d1,
				offsetTop: 0,
				//~ naText:'not found',
			});
			function li(u) {
				// Goto next tab
				new AMT___core_factory().nextTab();
				// Request
				new AMT___requests_factory().xhr_with_disk_cache({
					URL: u,
					check_pre_write_to_disk: function(options) { // Return TRUE to write to disk. Return FALSE to not write to disk.
						//console.log(JSON.parse(options.response.responseText));
						if(options.response.status != 200) {
							return false;
						}
						return true;
					},
					success_callback: function(options) {
						var rs = options.response.responseText;
						var dom = new DOMParser().parseFromString(rs, 'text/html');
						var js = dom.getElementById('stream-footer-embed-id-content');
						if (!js) return;
						js = js.innerHTML;
						//~ console.log(js);
						js = js.replace(/(^<!--|-->$)/g, '');
						//~ console.log(js);
						js = JSON.parse(js);
						console.log(js);
						//
						var sbm = true;
						if (js.industry) {
							o.q[0].value = js.industry;
							// Check
							if (o.q[0].options[o.q[0].selectedIndex].innerText != js.industry) {
								sbm = false;
							}
						} else sbm = false;
						if (js.size) {
							if (js.size == 'Myself Only') {
								js.size = '1-10';
							}
							js.size = js.size.replace(/ employees/, '');
							if (js.size == '501-1000') {
								js.size = '501-1,000';
							}
							if (js.size == '1001-5,000') {
								js.size = '1,001-5,000';
							}
							if (js.size == '5001-10,000') {
								js.size = '5,001-10,000';
							}
							if (js.size == '10001+') {
								js.size = '10,001+';
							}
							o.q[2].value = js.size;
							// Check
							if (o.q[2].options[o.q[2].selectedIndex].innerText != js.size) {
								sbm = false;
							}
						} else sbm = false;
						if (sbm) {
							doSubmit();
						}
					}
				});
			}
		}
		new run().f();
		return;
	}
