			//~ GM_addStyle('table {zoom:0.8;}');
			
			var td = document.getElementsByTagName('td');
			var o = {
				site: td[1].innerText.trim(),
				domain: '',
				rootBold: '',
				q: [
					document.getElementById('web_url')
				]
			}
			o.domain = o.site.replace(/^https?:\/\/(www\.|)([^\/]+)[\d\D]*/i, '$2');
			o.rootBold = o.domain.split('.').splice(0, o.domain.split('\.').length -1);
			console.log(o);
			/* BEGIN ITEMS */
			//
			var d1 = document.createElement('div');
			d1.setAttribute('style',
				'position:absolute;top:30px;left:0%;width:100%;height:600px;overflow:auto;background-color:#eee;border:1px solid blue;'
			);
			document.body.appendChild(d1);
