			// ...
			var ef = new AMT___events_factory();
			d3.  addEventListener('keydown', ef.keydown__blur_field, true);
			d3b. addEventListener('keydown', ef.keydown__blur_field, true);
			d3c. addEventListener('keydown', ef.keydown__blur_field, true);
			
