			function company_URL__load_skips() {
				GM_xmlhttpRequest({
					method: 'GET',
					url: MT___host+'/mturk/util.php?austin_load_skips=',
					onload: function (response) {
						var rs=response.responseText;
						
						//~ SKIP_SITES = rs.split("\n");
						
						var x = rs.split("\n");
						
						SKIP_SITES = {}; // ASSOC.
						
						// FULL
						for (var i in x) {
							SKIP_SITES[x[i]] = true;
						}
						
						// SUBDOMAINS!
						for (var i in x) {
							var y;
							if (y = /\.([^\.]+\.[^\.]+)$/.exec(x[i])) {
								SKIP_SITES[y[1]] = true;
							}
						}
						
						company_URL__SP_init();
					}
				});
			}
