					d.appendChild(el_inp_skip2__obj.el_btn);
					//~ // ...
					//~ d.appendChild(document.createElement('br'));
					// ...
					var pbody = document.createElement('p');
					pbody.setAttribute('style','');
					pbody.innerHTML = full;
