		function ashley_fraser_charities_ein__guidestar() {
			
			d1.innerHTML = '';
			
			var data = af; // INIT!!
			
			var u = encodeURIComponent(d2.value);
			
			data = data.replace(
				/ctl00%24SearchBar2%24txtKeywords=[^&]*/,
				'ctl00$SearchBar2$txtKeywords=' + u
			);
			data = data.replace(
				/ctl00%24phMainBody%24keywordsCarrollAreaChildCareCenter51401%24txtFieldValue=[^&]*/,
				'ctl00$phMainBody$keywordsCarrollAreaChildCareCenter51401$txtFieldValue=' + encodeURIComponent(u)
			);
			
			//console.log(data);
			
			GM_xmlhttpRequest({
				method: 'POST',
				url: 'http://www.guidestar.org/SearchResults.aspx',
				data: data,
				headers: {
					"Content-Type": "application/x-www-form-urlencoded"
				},
				onload: function(response) {
					var rs = response.responseText;
					
					if (response.status != 200) {
						console.log(response.status);
						return;
					}
					
					//console.log(rs);
					
					var r, r2;
					
					//HOPALONG ANIMAL RESCUE
					r = /<a href="(organizations\/(\d{2}-\d+)\/[^"]+)" id="ctl\d+_phMainBody_rptSearchResults_ctl\d+_aOrganizationName" class="red_link"><strong>[\r\n\t\s]*([^\r\n]+)[\r\n\t\s]*<\/strong><\/a>/g;
					
					r2 = /<span id="ctl\d+_phMainBody_rptSearchResults_ctl\d+_spAddress">([^<]+)/g;
					
					var m;
					var eldiv;
					var c = 0;
					var m2;
					
					while (m = r.exec(rs)) {
						//console.log(m);
						
						//~ r2 = 
						
						// nextindex
						m2 = r2.exec(rs)[1];
						
						
						eldiv = document.createElement('div');
						eldiv.setAttribute('style', 'border-bottom:1px solid #a2a2a2;cursor:pointer;');
						eldiv.eid = m[2];
						eldiv.guidestar_url = 'http://www.guidestar.org/' + m[1];
						eldiv.innerHTML = m[2] + "<br>" + MT__bold(__js_clean_html_str(m[3]), NAME.split(' ')) + '<br>' + m2;
						eldiv.onclick = function() {
							this.style.backgroundColor = 'LightGreen';
							document.getElementsByName('Q1Url')[0].value = this.eid;
							document.getElementsByName('Q1Url')[3].value = this.guidestar_url;
							//doSubmit();
						}
						d1.appendChild(eldiv);
						c = 1;
					}
					
					if (c == 0)
						d1.innerHTML = '0';
				}
			});
		}
		
