		function Ashley_Fraser_Email(out_div, search) {
			
			// Yahoo
			var u = 'http://search.yahoo.com/search?p=%2B'+encodeURIComponent(search); //%2B
			out_div.innerHTML = '';
			GM_xmlhttpRequest({
				method: 'GET',
				url: u,
				onload: function (response) {
					var rs=response.responseText;
					
					var rg = /yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g;
					
					if (rg.exec(rs) && rs.indexOf('Including results for') == -1) {
						rg.lastIndex = 0;
						rg=/yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g; // li
						var count = 0;
						var x, match, out;
						
						var r, m;
						var fb = '';
						var domain;
						
						//var out_id = out_div.id;
						while (match = rg.exec(rs)) {
							if (count >= 10)
								break;
							
							match[1] = decodeURIComponent(match[1]);
							//domain = match[1].replace(/^(http:\/\/[^\/]+)\/[^$]*$/, '$1');
							
							match[2] = match[2].replace(/<b>/g, '`');
							match[2] = match[2].replace(/<\/b>/g, '``');
							match[2] = match[2].replace(/<[^>]+>/g, ' ');
							match[2] = match[2].replace(/[<>]/g, ' ');
							//match[2] = match[2].replace(/'/g, "\'");
							match[2] = match[2].replace(/``/g, '</b>');
							match[2] = match[2].replace(/`/g, '<b>');
							
							x = match[1];
							
							// trailing
							var domain = x.replace(/(\w+)\/[^$]*$/, '$1'); //trailing 0, & slash
							
							// leading
							//x = x.replace(/^https?:\/\/(www\.|)/i, '');
							
							if (__js_inarray(SKIP_SITES, domain)) {//border-top:1px solid #3a4d3a;border-bottom:1px solid #3a4d3a;
								out_div.innerHTML += '\
									<p style="">\
									x'+domain+'\
									</p>';
								continue;
							}
							
							out_div.innerHTML += '\
								<p>\
								<input type="button" value="'+x+'" class="exe" style="width:auto;" > \
								<a href="'+match[1]+'" target="_blank">link</a> \
								<a href="'+match[1]+'" target="d2">ifr</a> \
								<input type="button" value=" S " id="'+domain+'" class="exe-skip" style="width:auto;" > \
								<br >'+match[1]+'\
								<br >'+match[2]+'\
								</p>';
								
							count++;
						}
						
						if (count > 0) {
							out_div.innerHTML += '<div style="height:1000px;">&nbsp;</div>';
						}
						
						var x = document.getElementsByClassName('exe');
						for (var i in x) {
							x[i].onclick = function() {
								this.style.backgroundColor = 'lime';
								d2.src = this.value;
							}
						}
						var x = document.getElementsByClassName('exe-skip');
						for (var i in x) {
							x[i].onclick = function() {
								this.style.backgroundColor = 'LightGreen';
								var btn = this;
								GM_xmlhttpRequest({
									method: 'GET',
									url: MT___host+'/mturk/util.php?ashley_fraser_email__load_skips='+encodeURIComponent(this.id),
									onload: function (response) {
										var rs=response.responseText;
										btn.value = ' ---X--- ';
										SKIP_SITES.push(btn.id);
									}
								});
							}
						}
					} else
						out_div.innerHTML = '0';
				}
			});
		}
