		// NAME_ARRAY
		// !! Scrape the contexts for name matching !!
		
		// results_array[]
		// [{r1}, {r2}, ... {r N}]
		/*
		{
		email_email: 'str email',
		email_contexts: ['str context 1','str context 2', ... 'str context N'],
		url: 'str url'
		}
		
		** add email_contexts_contains_name: (Boolean)
		
		*/
		function MT_Project_Find_Web_Info__scrapy_process_response(scrapy_jobid, scrapy_results_object, seed_object) {
			
			// set scrapy result array of this
			var x = document.getElementsByClassName(seed_object.btn_className);
			for (var i in x) {
				if (i == 'length') break;
				//x[i].scrapy__array_json_list = array_json_list.matches;
				x[i].scrapy_results_object = scrapy_results_object;
			}
			

			
			// Display results amounts?
			if (scrapy_results_object.matches.length == 0) {
			
			//if (scrapy_results_object.length == 0 || scrapy_results_object[0] == '') {
				var x = document.getElementsByClassName(seed_object.btn_className);
				for (var i in x) {
					if (i == 'length') break;
					// update values
					x[i].value += '*0*';
					// styles
					x[i].style.border = '';
					x[i].style.backgroundColor = 'teal';
					// onclick
					x[i].onclick = function() {
					}
				}
			} else {
				var x = document.getElementsByClassName(seed_object.btn_className);
				for (var i in x) {
					if (i == 'length') break;
					// update values
					x[i].value += '*' +scrapy_results_object.matches.length+ '*';
					// styles
					x[i].style.border = '6px solid #a2a2a2';
					// onclick
					x[i].onclick = function() {
						MT_Project_Find_Web_Info__scraper_display_result(this, this.scrapy_results_object); //btn, array
					}
				}
			}
		}
		// results_array[]
		// [{r1}, {r2}, ... {r N}]
		/*
		{
		email_email: 'str email',
		email_contexts: ['str context 1','str context 2', ... 'str context N'],
		url: 'str url'
		}
		 
		result . email_contexts_contains_name: (Boolean)
		*/
		function MT_Project_Find_Web_Info__scraper_display_result(btn, scrapy_results_object) {
			
			var out_div = d2;
			
			out_div.innerHTML = '';
			
			console.log(btn);
			console.log(scrapy_results_object);
			
			// scrollIntoView()?
			
			var el_select = document.createElement('select');
			out_div.appendChild(el_select);
			
			el_select.setAttribute('style','display:inline;width:98%;height:140px;');
			el_select.multiple = 'multiple';
			for (var i in scrapy_results_object.matches) {
				
				rslt = scrapy_results_object.matches[i];
				
				// add option
				el_option = document.createElement('option');
				el_option.value = rslt.email_email;
				el_option.innerText = rslt.email_email;
				// add email_contexts_contains_name !!
				if (rslt.email_contexts_contains_name) {
					el_option.setAttribute('style', 'background-color:LightGreen;color:blue;');
				}
				el_option.matches = rslt;
				el_select.appendChild(el_option);
			}
			el_select.onchange = function() {
				MT_Project_Find_Web_Info__scraper_display_result__selectChange(
					this.options[this.selectedIndex].matches // ?
				);
			}
			for (var i = 0; i<20; i++) {// append blank lines!
				// add option
				el_option = document.createElement('option');
				el_option.value = '';
				el_option.innerText = '';
				el_select.appendChild(el_option);
			}
			
			// urls select
			var el_select2 = document.createElement('select');
			out_div.appendChild(el_select2);
			el_select2.setAttribute('style','display:inline;width:98%;height:140px;');
			el_select2.multiple = 'multiple';
			el_select2.onclick = function() {
				if (this.value == '') return;
				window.open(this.value,'new');
			}
			// urls
			console.log(scrapy_results_object.urls.complete_high_to_low);
			for (var i in scrapy_results_object.urls.complete_high_to_low) {
				
				rslt = scrapy_results_object.urls.complete_high_to_low[i]; // {.url, .priority}
				
				// add option
				el_option = document.createElement('option');
				el_option.value = rslt.url;
				el_option.innerText = rslt.url;
				// color
				var bg;
				switch(rslt.priority) {
					case 'high':
						bg = 'LightGreen';
						break;
					case 'low':
						bg = 'Orange';
						break;
					case 'none':
						bg = '#fff';
						break;
					case 'outside':
						bg = 'pink';
						break;
				}
				el_option.setAttribute('style', 'background-color:'+bg+';');
				el_select2.appendChild(el_option);
			}
			for (var i = 0; i<20; i++) {// append blank lines!
				// add option
				el_option = document.createElement('option');
				el_option.value = '';
				el_option.innerText = '';
				el_select2.appendChild(el_option);
			}
			
			// br
			out_div.appendChild(document.createElement('br'));
			
			// auto-click first email
			if (scrapy_results_object.matches.length > 0) {
				MT_Project_Find_Web_Info__scraper_display_result__selectChange(
					el_select.options[0].matches
				);
			}
			
			out_div.appendChild(document.createElement('br'));
		}
		function MT_Project_Find_Web_Info__scraper_display_result__selectChange(results_array) {
			
			var out_div = d2;
			
			var old_divs = out_div.getElementsByTagName('div');
			for (var i = old_divs.length - 1; i>=0; i--) {
				old_divs[i].parentNode.removeChild(old_divs[i]);
			}
			
			var email_contexts = results_array.email_contexts;
			var url = results_array.url;
			
			var el_div = document.createElement('div');
			el_div.setAttribute('style','width:100%;height:40px;overflow:hidden;border:1px solid #a2a2a2;');
			//el_div.innerText = url;
			
			var el_a = document.createElement('a');
			el_a.href = url;
			el_a.target = '_blank';
			el_a.innerText = url;
			el_div.appendChild(el_a);

			out_div.appendChild(el_div);
			
			for (var j in email_contexts) {
				var context = email_contexts[j]	.replace(/<[^>]*>/g, ' ').replace(/[<>]/g, ' ');
				context = __js_clean_html_str(context);
				context = context				.replace(/<[^>]*>/g, ' ').replace(/[<>]/g, ' ');
				context = context.trim();
				context = context.replace(/[\t\s]*[\r\n]+[\t\s]*/g, '<br>');
				context = context.replace(/\t/g, '&nbsp;&nbsp;');
				context = context.replace(/\s{2,}/g, '&nbsp;&nbsp;');
				context = context.replace(
					new RegExp('(' + __js_escape_regEx(results_array.email_email) + ')', 'gi'),
					'<span style="zoom:1.2;color:DarkGreen;">$1</span>'
				);
				//context = MT__bold(context, NAME_ARRAY);
				
				var el_div = document.createElement('div');
				el_div.setAttribute('style','cursor:pointer;width:98%;height:auto;overflow:auto;border-bottom:3px dashed #a2a2a2;');
				el_div.innerHTML = context;
				el_div.email = results_array.email_email;
				el_div.onclick = function() {
					this.style.backgroundColor = 'LightGreen';
					document.getElementById('Q4email').value = this.email;
					if (this.email.length > 6 && this.email.indexOf('@') != -1) {
						doSubmit();
					}
				}
				out_div.appendChild(el_div);
			}
		}
