		function Lauren_us_news_get_OCT2(id) {// /best-colleges/depaul-university-1671/academics
			GM_xmlhttpRequest({
				method: 'GET',
				url: 'http://premium.usnews.com'+id+'/academics',
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status != 200) return;
					
					var r, r2;
					
					r = /The student-faculty ratio at [^\r\n]+[\r\n\t\s]+(\d+:1), and the school has ([\d\.]+) percent/.exec(rs);
					if (r) {
						q2.value = r[1];
						q1.value = r[2];
						if  (
							q1.value.length > 1 &&
							q2.value.length > 1
							)
						{
							doSubmit();
						}
					} else {
						
						r = /<td class="column-first">Class sizes<\/td>[\r\n\t\s]+<td class="column-last">[\r\n\t\s]+<span>[\r\n\t\s]+N\/A[\r\n\t\s]+<\/span>/.exec(rs);
						r2 = /<td class="column-first">Student-faculty ratio<\/td>[\r\n\t\s]+<td class="column-last">[\r\n\t\s]+<span>[\r\n\t\s]+N\/A[\r\n\t\s]+<\/span>/.exec(rs);
						
						if (r && r2) {
							q1.value = 'no data';
							q2.value = 'no data';
							doSubmit();
							return;
						} else {
							if (r) {//%
								q1.value = 'no data';
							}
							if (r2) {//:
								q2.value = 'no data';
							}
							
							r = / has ([\d\.]+) percent[\r\n\t\s]+of its classes with fewer than 20 students\./.exec(rs);
							
							if (r) {
								q1.value = r[1];
								if  (
									q1.value.trim().length > 1 &&
									q2.value.trim().length > 1
									)
								{
									doSubmit();
									return;
								}
							}
							
							r = /<td class="column-first">Student-faculty ratio<\/td>[\r\n\t\s]+<td class="column-last">[\r\n\t\s]+<span>[\r\n\t\s]+([\d:]+)[\r\n\t\s]+<\/span>/.exec(rs);
							
							if (r) {
								q2.value = r[1];
								if  (
									q1.value.trim().length > 1 &&
									q2.value.trim().length > 1
									)
								{
									doSubmit();
									return;
								}
							}
						}
					}
				}
			});
		}
