		function DavidFeldsott_yahoo__(url) {
			
			var u = url;
			u = u.replace(/[\?&]sk=[^&]+/g, '');
			u += (u.indexOf('?') != -1) ? '&sk=info' : '?sk=info'; //%2B
			d3c.value = u;
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: u,
				onload: function (response) {
					var rs = response.responseText;
					var r;
					var m;
					var emails = [];
					r = /([a-z0-9]+([_\.-][a-z0-9]+)*(@|[ ]{0,}\[at\][ ]{0,}|&#064;)([a-z0-9]+([\.-][a-z0-9]+)*)+\.[a-z]{2,})/gi;
					if (r.exec(rs)) {
						r.lastIndex = 0;
						//document.getElementById('Comments').value = 'Contact information is from: '+response.finalUrl;
						
						while (m = r.exec(rs)) {
							if (!__js_inarray(emails, __js_clean_html_str(m[1]))) {
								m[1] = __js_clean_html_str(m[1]);//.replace();
								document.getElementById('Q1Url').value += m[1]+' ';
								emails.push(__js_clean_html_str(m[1]));
							}
						}
						
						document.getElementById('Q1Url').value = document.getElementById('Q1Url').value.trim();
						document.getElementById('Q1Url').focus();
					}// else
					//	document.getElementById('Comments').value = 'N/A';
				}
			});
			
		}
		function DavidFeldsott_yahoo__(out_div, search, launch_first) {
			
			// Yahoo
			var u = 'http://search.yahoo.com/search?p=%2B'+encodeURIComponent(search); //%2B
			out_div.innerHTML = '';
			GM_xmlhttpRequest({
				method: 'GET',
				url: u,
				onload: function (response) {
					var rs=response.responseText;
					
					var rg = /yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g;
					
					if (rg.exec(rs) && rs.indexOf('Including results for') == -1) {
						rg.lastIndex = 0;
						rg=/yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g; // li
						var count = 0;
						var x, match, out;
						
						var r, m;
						var fb = '';
						
						//var out_id = out_div.id;
						while (match = rg.exec(rs)) {
							if (count >= 8)
								break;
							
							match[1] = decodeURIComponent(match[1]);
							
							match[2] = match[2].replace(/<b>/g, '`');
							match[2] = match[2].replace(/<\/b>/g, '``');
							match[2] = match[2].replace(/^[^>]+>/, ' '); // first close
							match[2] = match[2].replace(/<[^>]+>/g, ' ');
							match[2] = match[2].replace(/[<>]/g, ' ');
							//match[2] = match[2].replace(/'/g, "\'");
							match[2] = match[2].replace(/``/g, '</b>');
							match[2] = match[2].replace(/`/g, '<b>');
							
							//x = match[1];
							//x = x.replace(/(\w+)\/[\d\D]{0,}$/, '$1'); //trailing
							
							// emails
							//r = /([a-z0-9]+([_\.-][a-z0-9]+)*(@|[ ]{0,}\[at\][ ]{0,}|&#064;)([a-z0-9]+([\.-][a-z0-9]+)*)+\.[a-z]{2,})/gi;
							//if (r.exec(match[2])) {
							//	match[2] = match[2].replace(r, '<input type="button" value="$1" class="exe" style="background-color:pink;">');
							//}
							
							//if (match[1].indexOf('facebook.com') != -1) {
							//	fb = '<input type="button" value="- fb -" id="'+match[1]+'" class="exefb" >'
							//} else fb = '';
							
							out_div.innerHTML += '\
								<p>\
								<input type="button" value="'+match[1]+'" class="exe2" > \
								<a href="'+match[1]+'" target="_blank">link</a> \
								<a href="'+match[1]+'" target="d2">ifr</a> \
								'+fb+' \
								<br >'+match[2]+'\
								</p>';
								
							count++;
						}
						
						if (count > 0) {
							out_div.innerHTML += '<div style="height:1000px;">&nbsp;</div>';
						}
						
						var x = document.getElementsByClassName('exe');
						for (var i in x) {
							x[i].onclick = function() {
								this.style.backgroundColor = 'lime';
								document.getElementById('Q1Url').value = this.value;
								document.getElementById('Q1Url').focus();
							}
						}
						var x = document.getElementsByClassName('exe2');
						for (var i in x) {
							x[i].onclick = function() {
								this.style.backgroundColor = 'lime';
								//d2.src = this.value;
								document.getElementById('Q1Url').value = this.value;
								document.getElementById('Q1Url').focus();
							}
						}
						var x = document.getElementsByClassName('exe3');
						for (var i in x) {
							x[i].onclick = function() {
								this.style.backgroundColor = 'lime';
								window.open(this.id,'__name')
							}
						}
						/*var x = document.getElementsByClassName('exefb');
						for (var i in x) {
							x[i].onclick = function() {
								this.style.backgroundColor = 'lime';
								MobileSpinach_facebook(this.id);
							}
						}*/
					} else
						out_div.innerHTML = '0';
				}
			});
		}
