		function Brittany_Graham_contact_name_proxy() {
			// proxy
			var use_proxy = true;
			// get current
			COUNT_PROXY							= GM_getValue('AMT__Brittany_Graham_rv_emp_proxy');
			MAX_INIT_REQUESTS_WITHOUT_PROXY		= GM_getValue('AMT__Brittany_Graham_rv_emp_proxy_maxRequests');
			if (COUNT_PROXY == undefined || !COUNT_PROXY || COUNT_PROXY == NaN || !/^\d$/.exec(COUNT_PROXY))
				COUNT_PROXY = 0;
			if (MAX_INIT_REQUESTS_WITHOUT_PROXY == undefined || !MAX_INIT_REQUESTS_WITHOUT_PROXY || MAX_INIT_REQUESTS_WITHOUT_PROXY == NaN || !/^\d$/.exec(MAX_INIT_REQUESTS_WITHOUT_PROXY))
				MAX_INIT_REQUESTS_WITHOUT_PROXY = 2;
			// COUNT_PROXY
			if (COUNT_PROXY >= MAX_INIT_REQUESTS_WITHOUT_PROXY) {
				COUNT_PROXY = 0;
				use_proxy = false;
			}
			// increment
			else {
				COUNT_PROXY = Math.round(COUNT_PROXY * 1) + 1;
			}
			//console.log(COUNT_PROXY);
			
			// save value
			GM_setValue('AMT__Brittany_Graham_rv_emp_proxy', COUNT_PROXY);
			
			// OVERWRITE to always use proxy!!
			return true;
			
			// !!
			//return use_proxy;
			// !!
		}
		/** count proxy **/
		function Brittany_Graham_contact_name_useProxyInitSearch(first__, isManual__, u, out) { //console.log(AMT___POPUP___PROXY_REDACTED_);
			// init
			/** !!
			 * @global AMT___POPUP___PROXY_REDACTED_
			 */
			GM_xmlhttpRequest({
				method: "GET",
				url: AMT___POPUP___PROXY_REDACTED_+'/mturk/.scripts/google/get-page.php?u='+encodeURIComponent(u)+'&catch_include='+encodeURIComponent('Yahoo! - 999 Unable to process request at this time -- error 999'),
				onload: function(response) {
					//var rs = response.responseText;
				}
			});
			//url: 'http://192.168.1.3/mturk/.scripts/google/get-page.php?u='+encodeURIComponent(u)+'&catch_include='+encodeURIComponent('Yahoo! - 999 Unable to process request at this time -- error 999'),
			//url: 'http://localhost/mturk/.scripts/google/get-page.php?u='+encodeURIComponent(u)+'&catch_include='+encodeURIComponent('Yahoo! - 999 Unable to process request at this time -- error 999'),
			
			var xint = setInterval(function() {
				GM_xmlhttpRequest({ // init
					method: "GET",
					url: AMT___POPUP___PROXY_REDACTED_+'/mturk/.scripts/google/get-page.php?v='+encodeURIComponent(u),
					onload: function(response) {
						var rs = response.responseText;
						
						if (rs.trim() != '') {
							clearInterval(xint);
						} else
							return;
						
						Brittany_Graham_contact_name_processResp(first__, isManual__, rs, out);
					}
				})
			}, 1000);
		}
		
