		function Michael_Thompson_Manta(u) {
			GM_xmlhttpRequest({
				method: "GET",
				url: u,
				onload: function(response) {
					var rs = response.responseText;
					
					var r, r2;
					var q = document.getElementById('Annual Revenue');
					
					r = /<span id="profile-annual_revenue" class="">\$([^<]+)/.exec(rs);
					r2= /<th>Annual Revenue Estimate<\/th>[\r\n\t\s]+<td>\$([^<]+)/.exec(rs);
					
					if (r || r2) {
						if (r) {
							q.value = '$'+r[1];
						} else {
							q.value = '$'+r2[1];
						}
					} else if (rs.indexOf('Annual Revenue Estimate') == -1) {
						q.value = 'N/A'
					}
					q.focus();
				}
			});
		}
		function Michael_Thompson(u, out) {
			GM_xmlhttpRequest({
				method: "GET",
				url: u,
				onload: function(response) {
					var rs = response.responseText;
					
					out.innerHTML = '';
					
					var r = /yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g;
				
					if (r.exec(rs) && rs.indexOf('Including results for') == -1) {
						r.lastIndex = 0;
						r=/yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g; // li
						var count = 0;
						var r2;
						var x, y;
						var match;
						while (match = r.exec(rs)) {
							if (count >= 8)
								break;
							count++;
							
							match[1] = decodeURIComponent(match[1]);
							
							match[2] = match[2].replace(/<b>/g, '`');
							match[2] = match[2].replace(/<\/b>/g, '``');
							match[2] = match[2].replace(/<[^>]+>/g, ' ');
							match[2] = match[2].replace(/[<>]/g, ' ');
							match[2] = match[2].replace(/``/g, '</b>');
							match[2] = match[2].replace(/`/g, '<b>');
							
								
							out.innerHTML += '\
								<input type="button" value="'+match[1]+'" class="exe"  style="width:48%;text-align:left;" > \
								<br >\
								'+match[2] + '\
								<hr >\
								';
							
							count++;
						}
						
						var x = document.getElementsByClassName('exe');
						for (var i in x) {
							x[i].onclick = function() {
								this.style.backgroundColor = 'lime';
								Michael_Thompson_Manta(this.value);
							}
						}
					} else {
						out.innerHTML = '0';
					}
				}
			});
		}
		
