		function KristinHowe_agent_photo_layoutChangeType(cycle_to_next) {
			//
			var x = GM_getValue('MT___KristinHowe_agent_photos_layoutChangeType');
			if (x == undefined || !x) {
				x = 0;
			}
			if (cycle_to_next) {
				x = x*1 + 1;
				x = (x >= 3) ? 0 : x; // reset
				GM_setValue('MT___KristinHowe_agent_photos_layoutChangeType', x);
			}
			// 1/2
			if (x == 1 || x == 2) {
				d1.style.height = ''; //800
				try {
					d3.style.visibility = 'visible';
					d3b.style.visibility = 'visible';
				} catch(e) {}
			} else { // 3
				d1.style.height = '800px';
				try {
					d3.style.visibility = 'hidden';
					d3b.style.visibility = 'hidden';
				} catch(e) {}
			}
			d2c.value = 'cycle'+x;
			//d2c.value = 'cycle'+GM_getValue('MT___KristinHowe_agent_photos_layoutChangeType');
		}
		/**
		 * function kristin_howe_photos_yahoo_bot
		 */
		function kristin_howe_photos_yahoo_bot() {
			
			this.visited_urls_array = [];
			
			this.success_urls_array = [];
			
			this.yahoo_response_array;
			
			this.xhrSetTimeout;
			
			this.numRun = 0;
			
			this.tmp_name;
			
			this.__init_globals = function() {
				// 
				AMT___POPUP__initializeGlobals(
					this.__init //KH_YAHOO_BOT
				);
			}
			this.__init = function() { // TRY VARIATIONS // var all_names
				var req_proxy;
				//
				if (this.numRun == undefined)
					this.numRun = 0;
				//
				var tmp_name = NAME;
				if (this.numRun == 0) {			//console.log('y0');
					this.numRun++;
				} else if (this.numRun == 1) {	//console.log('y');
					this.numRun++;
					var x = tmp_name.split(' ');
					if (x.length == 3)
						tmp_name = x[0] + ' ' + x[2]; // FIRST / LAST
					else if (AMT__Global_Vars.isPreview) {
						AMT___Floater.skip();
						return;
					}
				} else {//console.log('y2');
					AMT___Floater.skip();
					return;
				}
				KH_YAHOO_BOT.tmp_name = tmp_name; // this !?
				
				//
				req_proxy = new AMT___xhr_PROXY_REDACTED_({
					url: 'http://search.yahoo.com/search?p=%2B'+encodeURIComponent('"' + tmp_name + '" site:' + SITE),
					yahoo_array: true
				});
				req_proxy.proxy_init();
				req_proxy.proxy_waitComplete(
					KH_YAHOO_BOT.setYahooResponse
				);
				return;
			}
			this.setYahooResponse = function(rs) {
				KH_YAHOO_BOT.yahoo_response_array = rs;
				KH_YAHOO_BOT.processYahooResponse();
			}
			this.processYahooResponse = function() { // [ [1,2], [1,2], [1,2] ], seed_arg1
				
				if (KH_YAHOO_BOT.xhrSetTimeout)
					clearTimeout(KH_YAHOO_BOT.xhrSetTimeout);
				
				var l = KH_YAHOO_BOT.yahoo_response_array.length;
				if (l == 0) {
					// quit!
					//AMT___Floater.skip();
					this.__init(); // TRY ONCE MORE!!
					return;
				}
				
				//~ if (KH_YAHOO_BOT.success_urls_array.length >= 2) {
					//~ 
					//~ return;
				//~ }
				
				// here?
				var item = KH_YAHOO_BOT.yahoo_response_array.shift(); // url, match_blurb
				var url = item[0];
				
				if (__js_inarray(this.visited_urls_array, url)) {
					this.processYahooResponse();
					return;
				}
				
				// here?
				this.xhrPageScrape(url);
			}
			this.xhrPageScrape = function(url) {
				
				KH_YAHOO_BOT.visited_urls_array.push(url);
				
				var url = url;
				
				KH_YAHOO_BOT.xhrSetTimeout = setInterval(function() {
					KH_YAHOO_BOT.processYahooResponse();
				}, 12000);
				
				GM_xmlhttpRequest({
					method: 'GET',
					url: url,
					timeout: 6000,
					ontimeout: function (response) {
						clearTimeout(KH_YAHOO_BOT.xhrSetTimeout);
						KH_YAHOO_BOT.processYahooResponse();
					},
					onerror: function (response) {
						clearTimeout(KH_YAHOO_BOT.xhrSetTimeout);
						KH_YAHOO_BOT.processYahooResponse();
					},
					onload: function (response) {
						var rs = response.responseText;
						
						clearTimeout(KH_YAHOO_BOT.xhrSetTimeout);
						
						if (response.status != 200) {
							KH_YAHOO_BOT.processYahooResponse();
							return;
						}
						
						// here?
						// is name on page?
						var words_only = rs.replace(/[^\w]/g, '');
						
						var name_words_only = NAME					.replace(/[^\w]/g, '');
						var name_words_only2= KH_YAHOO_BOT.tmp_name	.replace(/[^\w]/g, '');
						
						if  (
								(
								(new RegExp(__js_escape_regEx(name_words_only), 'i')) .exec(words_only) &&
								name_words_only.length > 4
								) ||
								(
								(new RegExp(__js_escape_regEx(name_words_only2), 'i')).exec(words_only) &&
								name_words_only2.length > 4
								) ||
								
								'debug' == ''
							)
						{
							KH_YAHOO_BOT.success_urls_array.push(url); //xx response.finalUrl
							
							// at least two "successful"?
							// else go back to process more yahoo
							if (KH_YAHOO_BOT.success_urls_array.length >= 2 || 'debug' == '') {
								KH_YAHOO_BOT.load_iframe_and_or_accept_job();
							} else {
								KH_YAHOO_BOT.load_iframe_and_or_accept_job(); // goes with 1
								KH_YAHOO_BOT.processYahooResponse();
							}
						}
						// continue scraping
						else
						{
							KH_YAHOO_BOT.processYahooResponse();
						}
						// 
					}
				});
			}
			this.load_iframe_and_or_accept_job = function() {
				console.log('accept');
				if (AMT__Global_Vars.isPreview) {
					AMT___Floater.accept();
					return;
				}
				
				// here?
				// d3, d3b
					
				if (d3.src == '')
					d3.src  = KH_YAHOO_BOT.success_urls_array[0];
				else if (d3b.src == '')
					d3b.src = KH_YAHOO_BOT.success_urls_array[1];
				else
					return;
				
				//~ // has two URLs
				//~ d3.src  = KH_YAHOO_BOT.success_urls_array[0];
				//~ d3b.src = KH_YAHOO_BOT.success_urls_array[1];
				
				// post message!
				window.addEventListener("message", AMT__Kristin_Howe_agent_photos__yahoo_bot__complete, false); // does not occur
				function AMT__Kristin_Howe_agent_photos__yahoo_bot__complete(event)
				{
					if (typeof event.data != 'object') return;
					if (event.data.key != 'AMT__Kristin_Howe_agent_photos__yahoo_bot__complete') return;
					
					// img src
					kristin_howe_photos_photoIs200(event.data.data);
				}
				var ifr_intv = setInterval(function() {
					d3.contentWindow.postMessage( {task: 'AMT__Kristin_Howe_agent_photos__yahoo_bot', agent_name: NAME}, "*"); // !!
					d3b.contentWindow.postMessage({task: 'AMT__Kristin_Howe_agent_photos__yahoo_bot', agent_name: NAME}, "*"); // !!
				}, 400);
			}
		}
		
		// INIT
		// !!
		var KH_YAHOO_BOT = new kristin_howe_photos_yahoo_bot();
