			/**
			 * create_title_annotation
			 * 
			 * e.g. {
						title: dom.title,
						product_url: result_object.url
					}
			 */
			function create_title_annotation(options) {
				var buttons = new AMT___items_factory().create_annotation_to_output_fields({
					textToAnnotate: options.title,
					output_fields: [ o.q[0] ],
					callback_mouseup: function(addField) {
						// Remove trailing commas
						addField.value = addField.value.replace(/ *[,\-;:]*$/g, '');
						addField.value = addField.value.replace(/^ *,*/, '');
						addField.value = addField.value.replace(/^ *-*/, ''); // etc.
						o.q[1].value = options.product_url;
					},
					//~ appendToField: true,
					//~ appendToField_glue: '\n',
					//~ delimeter: '',
					focusToField: true,
					style: 'border-radius:2px;border:0;zoom:1.0;background-color:#fff;cursor:pointer;padding:1px 4px;',
				});
				d4c.appendChild(buttons);
			}
			/**
			 * A9_Snaptell_VSR__yahoo_complete
			 */
			// ...
			// Scrape the first two results in each div.
			// Do this using ...
			// 0=url
			// 1=full
			function A9_Snaptell_VSR__yahoo_complete(rs, seed_argument) {
				var out = seed_argument;
				var num_good_results = 0;
				for (var i in rs) {
					// domain, link iframe, link blank, body
					// Max == 3
					// replace "m.target.com"
					rs[i][0] = rs[i][0].replace(/\/\/m\.target\.com/, '//www.target.com');
					// Domain
					var domain = rs[i][0];
					domain = domain.replace(/https?:\/\/(www\.|)/i, '');
					domain = domain.replace(/\/[\d\D]*/, '');
					// skips
					var el_inp_skip3__obj = new AMT___items_factory().create__input_skip_button3({
						domain: domain,
						load_file: 'VSR_Barcodes_Skips_File', 
						var_skip_sites: o.SKIP_SITES, 
						callback_function: false,
					});
					out.appendChild( el_inp_skip3__obj.el_button );
					if ( el_inp_skip3__obj.isSkip ) {
						continue; // Stops here
					} else {
						num_good_results++; // Increment num good results
					}
					//
					var tmp_url = rs[i][0];
					var tmp_url_replace_scripts = rs[i][0];
					if (i < 3) {
						var md5_filename = any_md5(rs[i][0], '0123456789ABCDEF');
						tmp_url = 'http://192.168.1.2/mturk/.cached/' + md5_filename;
						tmp_url_replace_scripts = 
							MT___host +
							'/mturk/util.php?AMT__output_html_from_URL=' +
							'&AMT__output_html_from_URL__options=' + encodeURIComponent(JSON.stringify(
								{
									htmlspecialchars: false, // FALSE!
									short_filename: md5_filename,
									replace_scripts: true
								}
							));
					}
					var host = rs[i][0].parseURL().host;
					// pdf
					var isPDF = /\.(pdf|xls|doc|docx|odt|odf)/i.exec(rs[i][0]);
					var bg_isPDF = (isPDF) ? 'background-color:pink;' : '';
					// ...
					var inp = document.createElement('input');
					inp.setAttribute('style', 'text-align:left;' + bg_isPDF);
					inp.type = 'button';
					inp.value = host;
					inp.host = host;
					inp.full_url = tmp_url;
					inp.output_url = rs[i][0];
					inp.onclick = A9_Snaptell_VSR__handle_clicks;
					out.appendChild(inp);
					// If 0,1,2 then scrape.
					if (i < 3 && !isPDF) {
						out.appendChild(document.createElement('br'));
						// First URL
						if  (
							d1.src == '' &&
							result.first_url == null &&
							!isPDF &&
							rs[i][0].indexOf('alibris.com') == -1 // No alibris (needs zoom fixed)
							)
						{
							result.first_url = tmp_url_replace_scripts;
							d1.output_url = rs[i][0]; //.output_url
						}
						var scrape_el = document.createElement('div');
						scrape_el.setAttribute('style',
							'display:inline-block;cursor:pointer;background-color:#eee;border:1px solid teal;margin:0 0 0 2px;'
						);
						out.appendChild(scrape_el);
						new AMT___items_factory().xhr_scrape_page(
							{
								parent_el: scrape_el,
								keyword_and_index_array: [upc],
								url: rs[i][0],
								short_filename: md5_filename,
								replace_absolute_url: true,
								callback_loaded: function(result_object) {
									setTimeout(function() {
										A9_Snaptell_VSR__load_first();
									}, 2000);
									// Create buttons from response TITLE
									// field here....
									var rs = result_object.response.responseText;
									var dom = new DOMParser().parseFromString(rs, 'text/html');
									if (dom.title) {
										create_title_annotation({
											title: dom.title,
											product_url: result_object.url
										});
									}
								}
							}
						);
						out.appendChild(document.createElement('br'));
					}
					// LINKS
					// Set link to tmp_url (OR rs[i][0])
					// If i < 3 then load the iframe 
					// without htmlspecialchars, with short_filename,
					// and WITH replace_scripts.
					var u;
					if (i < 3 && !isPDF)
						u = MT___host +
							'/mturk/util.php?AMT__output_html_from_URL=' +
							'&AMT__output_html_from_URL__options=' + encodeURIComponent(JSON.stringify(
								{
									htmlspecialchars: false, // FALSE!
									short_filename: md5_filename,
									replace_scripts: true
								}
							));
					else
						u = tmp_url;
					// IFR A
					var a = document.createElement('a');
					a.href = u;
					a.output_url = rs[i][0];
					a.innerText = '*IFR*';
					a.onclick = function() {
						if (!/\.(pdf|doc|docx)[\?$]/i.exec(this.href)) {
							d1.src = this.href;
							d1.output_url = this.output_url; //.output_url
						}
						return false;
					}
					out.appendChild(a);
					// ...
					if (i < 3 && !isPDF) {
						out.appendChild(document.createTextNode(' '));
						// Link for source
						var u = MT___host + '/mturk/util.php?AMT__output_html_from_URL=' +
								'&AMT__output_html_from_URL__options=' + encodeURIComponent(JSON.stringify(
									{
										htmlspecialchars: true, // TRUE!
										short_filename: md5_filename,
										replace_scripts: true
									}
								));
						var a = document.createElement('a');
						a.href = u;
						a.output_url = rs[i][0];
						a.innerText = '*SRC*';
						a.onclick = function() {
							d1.src = this.href;
							d1.output_url = this.output_url; //.output_url
							return false;
						}
						out.appendChild(a);
					}
					// Third link. This is ALWAYS going
					// to be tmp_url. So it is either 
					// the real link OR the cached link 
					// but NOT htmlspecialchars OR replace_scripts
					out.appendChild(document.createTextNode(' '));
					var a = document.createElement('a');
					a.href = tmp_url;
					a.target = '_blank';
					a.innerText = '*LINK*';
					out.appendChild(a);
					// External Link
					out.appendChild(document.createTextNode(' '));
					var a = document.createElement('a');
					a.href = rs[i][0];
					a.innerText = 'EX';
					a.target = '_blank';
					out.appendChild(a);
					// body
					var d = document.createElement('div');
					d.innerHTML = rs[i][1];
					out.appendChild(d);
					//...
					out.appendChild(document.createElement('hr'));
					
				}
				// For result
				var result_key = (out == d2) ? 'startpage' : 'yahoo';
				var rk = (out == d2) ? 'sp' : 'g'; // d2 & d2c
				// Num
				if (!rs.length) {
					out.innerText = '0';
					result[ result_key ] = false;
					d4a.result_buttons[rk].value += '✘';
				} else {
					var div = document.createElement('div');
					div.setAttribute('style', 'height:2000px;');
					out.appendChild(div);
					result[ result_key ] = true;
					d4a.result_buttons[rk].value += '✔';
					d4a.result_buttons[rk].style.backgroundColor = 'LightGreen';
				}
				// CALL NEXT
				A9_Snaptell_VSR__next();
				// Return status
				return {
					num_good_results: num_good_results
				}
			}
