		// function Fiber_Data_Co_MT__highLight()
		function Fiber_Data_Co_MT__highLight(o, arr, type) {
			
			arr.sort(function(a, b){
			  return b.length - a.length; // ASC -> a - b; DESC -> b - a
			});
			
			var x = o;
			var garb = new Array(); // garb not used!
			
			for (var i in arr) {
				if (
					arr[i].trim().length < 4 &&
					arr[i].trim().toLowerCase() != 'fax' // allow the word "fax" to be replaced
				) {
					continue;
				}
				if (arr[i] == 'b') {
					x = x.replace(/b([^>])/, '<b>$1'); //     b>
					x = x.replace(/([^\/<])b/, '$1</b>'); //  /<b
					//arr[i] = 
				} else {
					//x = x.replace(new RegExp('('+__js_escape_regEx(arr[i])+')', 'gi'), '<b>$1</b>');
					
					x = x.replace(new RegExp('('+__js_escape_regEx(arr[i])+')', 'gi'), '<b>$1</b>');
					
					//~ // replace numbers as 0000000000, 000000, 000-0000, (000) 000-0000, etc.
					//~ if (/^[\d\-\(\)\.]+$/.exec(arr[i])) {
						//~ var y = arr[i].split(''); // split into an array
						//~ var z = '';
						//~ for (var j in y) {
							//~ y[j] = '[\\-\\(\\)\\. ]*' + __js_escape_regEx(y[j]) + '[\\-\\(\\)\\. ]*';
							//~ z += y[j];
							//~ //z += __js_escape_regEx(y[j]);
						//~ }
						//~ //console.log(z);
						//~ x = x.replace(new RegExp('('+z+')', 'gi'), '<b>$1</b>');
					//~ }
					//~ // replace all others
					//~ else {
						//~ x = x.replace(new RegExp('('+__js_escape_regEx(arr[i])+')', 'gi'), '<b>$1</b>');
					//~ }
				}
			}
			
			x = x.replace(/<b>/g, '<strike>');
			x = x.replace(/<\/b>/g, '</strike>');
			
			return {"highlightString":x, "garb":garb}; // garb not used!
		}
