			// set "parseText" to textarea value
			parseText = txtarea.value;
			
			// replace emails with " email "
			//parseText = parseText.replace(/Â/gi, '');
			parseText = parseText.replace(/([a-z0-9]+([_\.-][a-z0-9]+)*(@|[ ]{0,}\[at\][ ]{0,}|&#064;)([a-z0-9]+([\.-][a-z0-9]+)*)+\.[a-z]{2,})/gi, ' $1 ');
			// replace "email" "phone" "fax" "facsimile"
			parseText = parseText.replace(/(e\-*mail|phone|tel\.|tele\-*phone|fax|facsimile|facs\.)/gi, ' $1 ');
			// extra spaces
			parseText = parseText.replace(/\s+/gi, ' ');
			parseText = parseText.trim();
			// original string to this point
			var parseText_tmp = parseText;
			
			// Is this an auto fill entry? This is based on regex match.
			//
			var arrAuto = parseText_tmp.split(' - ');
			// auto (on/off)
			if (arrAuto.length >= 2 && 1 == 1) {
				// i = 0,1,2;
				for (var i in arrAuto) {
					if (i > 2) break; // Only 0,1,2!
					var str_tmp = arrAuto[i];
					var regAuto = /phone ([^,$]+),?/i;
					if (regAuto.exec(arrAuto[i])) {
						var a = regAuto.exec(arrAuto[i])[1];
						document.getElementById('Answer_'+(i*7 + 4)+'_FreeText').value = a.trim();
						str_tmp = str_tmp.replace(regAuto, '');
						str_tmp = str_tmp.replace(regAuto, '');
					}
					var regAuto = /fax ([^,$]+),?/i;
					if (regAuto.exec(arrAuto[i])) {
						var a = regAuto.exec(arrAuto[i])[1];
						document.getElementById('Answer_'+(i*7 + 5)+'_FreeText').value = a.trim();
						str_tmp = str_tmp.replace(regAuto, '');
					}
					var regAuto = /email ([^,$]+),?/i;
					if (regAuto.exec(arrAuto[i])) {
						var a = regAuto.exec(arrAuto[i])[1];
						document.getElementById('Answer_'+(i*7 + 7)+'_FreeText').value = a.trim();
						str_tmp = str_tmp.replace(regAuto, '');
					}
					var regAuto = /^([^,$]+),?/; //name
					if (regAuto.exec(arrAuto[i])) {
						var a = regAuto.exec(arrAuto[i])[1];
						a = a.split(' ');
						if (a.length == 1) {
							document.getElementById('Answer_'+(i*7 + 3)+'_FreeText').value = a[0];
						} else if (a.length == 2) {
							document.getElementById('Answer_'+(i*7 + 1)+'_FreeText').value = a[0];
							document.getElementById('Answer_'+(i*7 + 3)+'_FreeText').value = a[1];
						} else if (a.length == 3) {
							document.getElementById('Answer_'+(i*7 + 1)+'_FreeText').value = a[0];
							document.getElementById('Answer_'+(i*7 + 2)+'_FreeText').value = a[1].substr(0, 1).toUpperCase() + '.';
							document.getElementById('Answer_'+(i*7 + 3)+'_FreeText').value = a[2];
						} else {
							document.getElementById('Answer_'+(i*7 + 1)+'_FreeText').value = a.slice(0, a.length - 1).join(' ');
							document.getElementById('Answer_'+(i*7 + 3)+'_FreeText').value = a[a.length - 1];
						}
						str_tmp = str_tmp.replace(regAuto, '');
					}
					str_tmp = str_tmp.trim().replace(/, *$/, '');
					if (str_tmp.length > 0) {
						document.getElementById('Answer_'+(i*7 + 6)+'_FreeText').value = str_tmp;
					}
				}
			}
			
